-- 1. Enrich catalog chapters with difficulty, weightage, hours, prerequisites & description
INSERT INTO public.chapters (id, subject_id, title, chapter_number, grade, unit_number, unit_name, estimated_hours, exam_weightage, difficulty, prerequisites, in_cbse_syllabus, description)
VALUES
  ('phy-units', 'cbse-11-physics', 'Units and Measurements', 1, '11', 1, 'Physical World and Measurement', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'SI units, fundamental and derived units, significant figures, dimensions of physical quantities, dimensional analysis and its applications.'),
  ('phy-vectors', 'cbse-11-physics', 'Motion in a Straight Line', 2, '11', 2, 'Kinematics', 6.0, 'critical', 'medium', ARRAY['phy-units']::TEXT[], true, 'Frame of reference, position-time graph, speed and velocity, uniform and non-uniform motion, instantaneous velocity, kinematic equations for uniformly accelerated motion.'),
  ('phy-motion-plane', 'cbse-11-physics', 'Motion in a Plane', 3, '11', 2, 'Kinematics', 8.0, 'critical', 'hard', ARRAY['phy-vectors']::TEXT[], true, 'Scalar and vector quantities, position and displacement vectors, equality of vectors, resolution of a vector, dot and cross products, projectile motion, uniform circular motion.'),
  ('phy-laws', 'cbse-11-physics', 'Laws of Motion', 4, '11', 3, 'Laws of Motion', 8.0, 'critical', 'hard', ARRAY['phy-motion-plane']::TEXT[], true, 'Intuitive concept of force, Inertia, Newton first, second, and third laws of motion, momentum, impulse, conservation of linear momentum, equilibrium of concurrent forces, static and kinetic friction, dynamics of circular motion.'),
  ('phy-work', 'cbse-11-physics', 'Work, Energy and Power', 5, '11', 4, 'Work, Energy and Power', 7.0, 'critical', 'medium', ARRAY['phy-laws']::TEXT[], true, 'Work done by a constant force and a variable force, kinetic energy, work-energy theorem, power, potential energy of a spring, conservative and non-conservative forces, conservation of mechanical energy, elastic and inelastic collisions.'),
  ('phy-system', 'cbse-11-physics', 'System of Particles and Rotational Motion', 6, '11', 5, 'Motion of System of Particles and Rigid Body', 9.0, 'critical', 'hard', ARRAY['phy-work']::TEXT[], true, 'Centre of mass of a two-particle system, momentum conservation and centre of mass motion, torque, angular momentum, conservation of angular momentum, moment of inertia, radius of gyration, values of moments of inertia for simple geometrical objects.'),
  ('phy-gravity', 'cbse-11-physics', 'Gravitation', 7, '11', 6, 'Gravitation', 6.0, 'high', 'medium', ARRAY['phy-work']::TEXT[], true, 'Kepler laws of planetary motion, universal law of gravitation, acceleration due to gravity and its variation with altitude and depth, gravitational potential energy and gravitational potential, escape velocity, orbital velocity of a satellite.'),
  ('phy-solids', 'cbse-11-physics', 'Mechanical Properties of Solids', 8, '11', 7, 'Properties of Bulk Matter', 5.0, 'medium', 'easy', ARRAY['phy-work']::TEXT[], true, 'Stress-strain relationship, Hooke law, Young modulus, bulk modulus, shear modulus of rigidity, Poisson ratio; elastic energy.'),
  ('phy-fluids', 'cbse-11-physics', 'Mechanical Properties of Fluids', 9, '11', 7, 'Properties of Bulk Matter', 7.0, 'critical', 'hard', ARRAY['phy-laws']::TEXT[], true, 'Pressure due to a fluid column; Pascal law and its applications, effect of gravity on fluid pressure. Viscosity, Stokes law, terminal velocity, streamline and turbulent flow, critical velocity, Bernoulli principle and its applications. Surface energy and surface tension, angle of contact, excess of pressure across a curved surface, capillary rise.'),
  ('phy-thermal', 'cbse-11-physics', 'Thermal Properties of Matter', 10, '11', 7, 'Properties of Bulk Matter', 6.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Heat, temperature, thermal expansion; thermal expansion of solids, liquids and gases, anomalous expansion of water; specific heat capacity; Cp, Cv - calorimetry; change of state - latent heat capacity. Heat transfer - conduction, convection and radiation, thermal conductivity, qualitative ideas of Blackbody radiation, Wien displacement law, Stefan law.'),
  ('phy-thermo', 'cbse-11-physics', 'Thermodynamics', 11, '11', 8, 'Thermodynamics', 6.0, 'critical', 'medium', ARRAY['phy-thermal']::TEXT[], true, 'Thermal equilibrium and definition of temperature (zeroth law of thermodynamics). Heat, work and internal energy. First law of thermodynamics. Isothermal and adiabatic processes. Second law of thermodynamics: reversible and irreversible processes.'),
  ('phy-kinetic', 'cbse-11-physics', 'Kinetic Theory', 12, '11', 9, 'Kinetic Theory of Gases', 5.0, 'high', 'easy', ARRAY['phy-thermo']::TEXT[], true, 'Equation of state of a perfect gas, work done in compressing a gas. Kinetic theory of gases - assumptions, concept of pressure. Kinetic interpretation of temperature; rms speed of gas molecules; degrees of freedom, law of equi-partition of energy and application to specific heat capacities of gases; concept of mean free path.'),
  ('phy-oscillations', 'cbse-11-physics', 'Oscillations', 13, '11', 10, 'Oscillations and Waves', 7.0, 'critical', 'hard', ARRAY['phy-work']::TEXT[], true, 'Periodic motion - time period, frequency, displacement as a function of time, periodic functions. Simple harmonic motion (S.H.M) and its equation; phase; oscillations of a loaded spring-restoring force and force constant; energy in S.H.M. Kinetic and potential energies; simple pendulum derivation of expression for its time period.'),
  ('phy-waves', 'cbse-11-physics', 'Waves', 14, '11', 10, 'Oscillations and Waves', 7.0, 'critical', 'hard', ARRAY['phy-oscillations']::TEXT[], true, 'Wave motion: Transverse and longitudinal waves, speed of travelling wave, displacement relation for a progressive wave, principle of superposition of waves, reflection of waves, standing waves in strings and organ pipes, fundamental mode and harmonics, Beats.'),
  ('chem-basic', 'cbse-11-chemistry', 'Some Basic Concepts of Chemistry', 1, '11', 1, 'Some Basic Concepts of Chemistry', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'General Introduction: Importance and scope of Chemistry. Nature of matter, laws of chemical combination, Dalton atomic theory: concept of elements, atoms and molecules. Atomic and molecular masses, mole concept and molar mass, percentage composition, empirical and molecular formula, chemical reactions, stoichiometry and calculations based on stoichiometry.'),
  ('chem-structure', 'cbse-11-chemistry', 'Structure of Atom', 2, '11', 2, 'Structure of Atom', 8.0, 'critical', 'hard', ARRAY['chem-basic']::TEXT[], true, 'Discovery of Electron, Proton and Neutron, atomic number, isotopes and isobars. Thomson model and its limitations. Rutherford model and its limitations, Bohr model and its limitations, dual nature of matter and light, de Broglie relationship, Heisenberg uncertainty principle, concept of orbitals, quantum numbers, shapes of s, p and d orbitals, rules for filling electrons in orbitals - Aufbau principle, Pauli exclusion principle and Hund rule, electronic configuration of atoms, stability of half-filled and completely filled orbitals.'),
  ('chem-periodic', 'cbse-11-chemistry', 'Classification of Elements and Periodicity in Properties', 3, '11', 3, 'Classification of Elements and Periodicity in Properties', 5.0, 'high', 'easy', ARRAY['chem-structure']::TEXT[], true, 'Significance of classification, brief history of the development of periodic table, modern periodic law and the present form of periodic table, periodic trends in properties of elements -atomic radii, ionic radii, inert gas radii, Ionization enthalpy, electron gain enthalpy, electronegativity, valency. Nomenclature of elements with atomic number greater than 100.'),
  ('chem-bonding', 'cbse-11-chemistry', 'Chemical Bonding and Molecular Structure', 4, '11', 4, 'Chemical Bonding and Molecular Structure', 9.0, 'critical', 'hard', ARRAY['chem-periodic']::TEXT[], true, 'Valence electrons, ionic bond, covalent bond, bond parameters, Lewis structure, polar character of covalent bond, covalent character of ionic bond, valence bond theory, resonance, geometry of covalent molecules, VSEPR theory, concept of hybridization, involving s, p and d orbitals and shapes of some simple molecules, molecular orbital theory of homonuclear diatomic molecules, hydrogen bond.'),
  ('chem-thermo', 'cbse-11-chemistry', 'Chemical Thermodynamics', 5, '11', 5, 'Chemical Thermodynamics', 8.0, 'critical', 'hard', ARRAY['chem-basic']::TEXT[], true, 'Concepts of System and types of systems, surroundings, work, heat, energy, extensive and intensive properties, state functions. First law of thermodynamics -internal energy and enthalpy, heat capacity and specific heat, measurement of Delta U and Delta H, Hess law of constant heat summation, enthalpy of bond dissociation, combustion, formation, atomization, sublimation, phase transition, ionization, solution and dilution. Second law of Thermodynamics (brief introduction). Introduction of entropy as a state function, Gibbs energy change for spontaneous and non-spontaneous processes, criteria for equilibrium. Third law of thermodynamics (brief introduction).'),
  ('chem-equilibrium', 'cbse-11-chemistry', 'Equilibrium', 6, '11', 6, 'Equilibrium', 9.0, 'critical', 'hard', ARRAY['chem-thermo']::TEXT[], true, 'Equilibrium in physical and chemical processes, dynamic nature of equilibrium, law of mass action, equilibrium constant, factors affecting equilibrium - Le Chatelier principle, ionic equilibrium- ionization of acids and bases, strong and weak electrolytes, degree of ionization, ionization of poly basic acids, acid strength, concept of pH, hydrolysis of salts, buffer solution, Henderson Equation, solubility product, common ion effect.'),
  ('chem-redox', 'cbse-11-chemistry', 'Redox Reactions', 7, '11', 7, 'Redox Reactions', 5.0, 'high', 'easy', ARRAY['chem-basic']::TEXT[], true, 'Concept of oxidation and reduction, redox reactions, oxidation number, balancing redox reactions, in terms of loss and gain of electrons and change in oxidation number, applications of redox reactions.'),
  ('chem-organic', 'cbse-11-chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 8, '11', 8, 'Organic Chemistry: Some Basic Principles and Techniques', 10.0, 'critical', 'hard', ARRAY['chem-bonding']::TEXT[], true, 'General introduction, methods of purification, qualitative and quantitative analysis, classification and IUPAC nomenclature of organic compounds. Electronic displacements in a covalent bond: inductive effect, electromeric effect, resonance and hyperconjugation. Homolytic and heterolytic fission of a covalent bond: free radicals, carbocations, carbanions, electrophiles and nucleophiles, types of organic reactions.'),
  ('chem-hydrocarbons', 'cbse-11-chemistry', 'Hydrocarbons', 9, '11', 9, 'Hydrocarbons', 10.0, 'critical', 'hard', ARRAY['chem-organic']::TEXT[], true, 'Classification of Hydrocarbons. Alkanes - Nomenclature, isomerism, conformation (ethane only), physical properties, chemical reactions including free radical mechanism of halogenation, combustion and pyrolysis. Alkenes - Nomenclature, structure of double bond (ethene), geometrical isomerism, physical properties, methods of preparation, chemical reactions: addition of hydrogen, halogen, water, hydrogen halides (Markownikov addition and peroxide effect), ozonolysis, oxidation, mechanism of electrophilic addition. Alkynes - Nomenclature, structure of triple bond (ethyne), physical properties, methods of preparation, chemical reactions: acidic character of alkynes, addition reaction of - hydrogen, halogens, hydrogen halides and water. Aromatic Hydrocarbons: Introduction, IUPAC nomenclature, benzene: resonance, aromaticity, chemical properties: mechanism of electrophilic substitution. Nitration, sulphonation, halogenation, Friedel Craft alkylation and acylation, directive influence of functional group in mono-substituted benzene. Carcinogenicity and toxicity.'),
  ('math-sets', 'cbse-11-mathematics', 'Sets', 1, '11', 1, 'Sets and Functions', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Sets and their representations, empty set, finite and infinite sets, equal sets, subsets, subsets of a set of real numbers, universal set, Venn diagrams, union and intersection of sets, difference of sets, complement of a set, properties of complement.'),
  ('math-relations', 'cbse-11-mathematics', 'Relations and Functions', 2, '11', 1, 'Sets and Functions', 7.0, 'critical', 'medium', ARRAY['math-sets']::TEXT[], true, 'Ordered pairs. Cartesian product of sets. Number of elements in the Cartesian product of two finite sets. Cartesian product of the set of reals with itself. Definition of relation, pictorial diagrams, domain, co-domain and range of a relation. Function as a special type of relation. Pictorial representation of a function, domain, co-domain and range of a function. Real valued functions, domain and range of these functions, constant, identity, polynomial, rational, modulus, signum, exponential, logarithmic and greatest integer functions, with their graphs. Sum, difference, product and quotients of functions.'),
  ('math-trig', 'cbse-11-mathematics', 'Trigonometric Functions', 3, '11', 1, 'Sets and Functions', 9.0, 'critical', 'hard', ARRAY['c10-math-8']::TEXT[], true, 'Positive and negative angles. Measuring angles in radians and in degrees and conversion from one measure to another. Definition of trigonometric functions with the help of unit circle. Truth of the identity sin^2 x + cos^2 x = 1, for all x. Signs of trigonometric functions. Domain and range of trigonometric functions and their graphs. Expressing sin (x+-y) and cos (x+-y) in terms of sin x, sin y, cos x & cos y and their simple applications. Identities related to sin 2x, cos 2x, tan 2x, sin 3x, cos 3x and tan 3x.'),
  ('math-complex', 'cbse-11-mathematics', 'Complex Numbers and Quadratic Equations', 4, '11', 2, 'Algebra', 6.0, 'high', 'medium', ARRAY['c10-math-4']::TEXT[], true, 'Need for complex numbers, especially sqrt(-1), to be motivated by inability to solve some of the quadratic equations. Algebraic properties of complex numbers. Argand plane. Statement of Fundamental Theorem of Algebra, solutions of quadratic equations (with real coefficients) in the complex number system.'),
  ('math-inequalities', 'cbse-11-mathematics', 'Linear Inequalities', 5, '11', 2, 'Algebra', 4.0, 'medium', 'easy', ARRAY['math-sets']::TEXT[], true, 'Linear inequalities. Algebraic solutions of linear inequalities in one variable and their representation on the number line.'),
  ('math-permutations', 'cbse-11-mathematics', 'Permutations and Combinations', 6, '11', 2, 'Algebra', 8.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Fundamental principle of counting. Factorial n. (n!). Permutations and combinations, derivation of Formulae for nPr and nCr and their connections, simple applications.'),
  ('math-binomial', 'cbse-11-mathematics', 'Binomial Theorem', 7, '11', 2, 'Algebra', 5.0, 'high', 'medium', ARRAY['math-permutations']::TEXT[], true, 'Historical perspective, statement and proof of the binomial theorem for positive integral indices. Pascal triangle, simple applications.'),
  ('math-sequences', 'cbse-11-mathematics', 'Sequences and Series', 8, '11', 2, 'Algebra', 7.0, 'critical', 'medium', ARRAY['c10-math-5']::TEXT[], true, 'Sequence and Series. Arithmetic Progression (A. P.). Arithmetic Mean (A.M.) Geometric Progression (G.P.), general term of a G.P., sum of n terms of a G.P., infinite G.P. and its sum, geometric mean (G.M.), relation between A.M. and G.M.'),
  ('math-straight', 'cbse-11-mathematics', 'Straight Lines', 9, '11', 3, 'Coordinate Geometry', 7.0, 'critical', 'medium', ARRAY['c10-math-7']::TEXT[], true, 'Brief recall of two dimensional geometry from earlier classes. Slope of a line and angle between two lines. Various forms of equations of a line: parallel to axis, point -slope form, slope-intercept form, two-point form, intercept form. Distance of a point from a line.'),
  ('math-conic', 'cbse-11-mathematics', 'Conic Sections', 10, '11', 3, 'Coordinate Geometry', 8.0, 'critical', 'hard', ARRAY['math-straight']::TEXT[], true, 'Sections of a cone: circles, ellipse, parabola, hyperbola. Standard equations and simple properties of parabola, ellipse and hyperbola. Standard equation of a circle.'),
  ('math-3d', 'cbse-11-mathematics', 'Introduction to Three-dimensional Geometry', 11, '11', 3, 'Coordinate Geometry', 4.0, 'medium', 'easy', ARRAY['c10-math-7']::TEXT[], true, 'Coordinate axes and coordinate planes in three dimensions. Coordinates of a point. Distance between two points and section formula.'),
  ('math-limits', 'cbse-11-mathematics', 'Limits and Derivatives', 12, '11', 4, 'Calculus', 9.0, 'critical', 'hard', ARRAY['math-trig']::TEXT[], true, 'Derivative introduced as rate of change both as that of distance and function. Intuitive idea of limit. Limits of polynomials and rational functions, trigonometric functions. Definition of derivative, relate it to scope of tangent of the curve, derivative of sum, difference, product and quotient of functions. Derivatives of polynomial and trigonometric functions.'),
  ('math-stats', 'cbse-11-mathematics', 'Statistics', 13, '11', 5, 'Statistics and Probability', 5.0, 'high', 'medium', ARRAY['c10-math-13']::TEXT[], true, 'Measures of Dispersion: Range, Mean deviation, variance and standard deviation of ungrouped/grouped data.'),
  ('math-probability', 'cbse-11-mathematics', 'Probability', 14, '11', 5, 'Statistics and Probability', 6.0, 'high', 'medium', ARRAY['math-sets']::TEXT[], true, 'Events; occurrence of events, not, and and or events, exhaustive events, mutually exclusive events, Axiomatic (set theoretic) probability, connections with other theories of earlier classes. Probability of an event, probability of not, and and or events.'),
  ('c11-bio-1', 'cbse-11-biology', 'The Living World', 1, '11', 1, 'Diversity in the Living World', 4.0, 'medium', 'easy', ARRAY[]::TEXT[], true, 'Biodiversity, need for classification, three domains of life, taxonomy and systematics, concept of species and taxonomical hierarchy, binomial nomenclature.'),
  ('c11-bio-2', 'cbse-11-biology', 'Biological Classification', 2, '11', 1, 'Diversity in the Living World', 6.0, 'high', 'medium', ARRAY['c11-bio-1']::TEXT[], true, 'Five kingdom classification; salient features and classification of Monera, Protista and Fungi into major groups; Lichens, Viruses, Viroids and Prions.'),
  ('c11-bio-3', 'cbse-11-biology', 'Plant Kingdom', 3, '11', 1, 'Diversity in the Living World', 6.0, 'high', 'medium', ARRAY['c11-bio-2']::TEXT[], true, 'Classification of plants into major groups; Salient features and distinguish characteristics of Algae, Bryophytes, Pteridophytes, Gymnosperms (Angiosperms salient features and life cycles).'),
  ('c11-bio-4', 'cbse-11-biology', 'Animal Kingdom', 4, '11', 1, 'Diversity in the Living World', 8.0, 'critical', 'hard', ARRAY['c11-bio-2']::TEXT[], true, 'Salient features and classification of animals: non-chordates up to phyla level and chordates up to class level (Porifera, Coelenterata, Ctenophora, Platyhelminthes, Aschelminthes, Annelida, Arthropoda, Mollusca, Echinodermata, Hemichordata, Chordata).'),
  ('c11-bio-5', 'cbse-11-biology', 'Morphology of Flowering Plants', 5, '11', 2, 'Structural Organisation in Animals and Plants', 6.0, 'high', 'medium', ARRAY['c11-bio-3']::TEXT[], true, 'Morphology of different parts of flowering plants: root, stem, leaf, inflorescence, flower, fruit and seed. Description of family Solanaceae and Fabaceae/Asteraceae.'),
  ('c11-bio-6', 'cbse-11-biology', 'Anatomy of Flowering Plants', 6, '11', 2, 'Structural Organisation in Animals and Plants', 6.0, 'high', 'medium', ARRAY['c11-bio-5']::TEXT[], true, 'Anatomy and functions of tissue systems in dicots and monocots: Meristematic and permanent tissues, epidermis, ground tissue, vascular tissue; internal structure of root, stem, and leaf.'),
  ('c11-bio-7', 'cbse-11-biology', 'Structural Organisation in Animals', 7, '11', 2, 'Structural Organisation in Animals and Plants', 6.0, 'high', 'medium', ARRAY['c11-bio-4']::TEXT[], true, 'Animal tissues (Epithelial, Connective, Muscular, Neural tissues); Morphology, anatomy, and functions of digestive, circulatory, respiratory, nervous, and reproductive systems of Frog.'),
  ('c11-bio-8', 'cbse-11-biology', 'Cell: The Unit of Life', 8, '11', 3, 'Cell: Structure and Function', 7.0, 'critical', 'medium', ARRAY['c9-sci-5']::TEXT[], true, 'Cell theory and cell as the basic unit of life, structure of prokaryotic and eukaryotic cells; Plant cell and animal cell; cell envelope; cell membrane, cell wall; cell organelles - structure and function.'),
  ('c11-bio-9', 'cbse-11-biology', 'Biomolecules', 9, '11', 3, 'Cell: Structure and Function', 7.0, 'critical', 'hard', ARRAY['c11-bio-8', 'chem-basic']::TEXT[], true, 'Chemical constituents of living cells: biomolecules, structure and function of proteins, carbohydrates, lipids, nucleic acids; Enzyme - types, properties, enzyme action.'),
  ('c11-bio-10', 'cbse-11-biology', 'Cell Cycle and Cell Division', 10, '11', 3, 'Cell: Structure and Function', 6.0, 'critical', 'medium', ARRAY['c11-bio-8']::TEXT[], true, 'Cell cycle, phases of cell cycle (G1, S, G2, M phase); Mitosis, cytokinesis, significance of mitosis; Meiosis I and Meiosis II, stages of Prophase I, crossing over and significance.'),
  ('c11-bio-11', 'cbse-11-biology', 'Photosynthesis in Higher Plants', 11, '11', 4, 'Plant Physiology', 7.0, 'critical', 'hard', ARRAY['c11-bio-8']::TEXT[], true, 'Site of photosynthesis, photosynthetic pigments, light reaction, electron transport system, cyclic and non-cyclic photophosphorylation, chemiosmotic hypothesis, Calvin C3 cycle, Hatch-Slack C4 pathway, photorespiration, factors affecting photosynthesis.'),
  ('c11-bio-12', 'cbse-11-biology', 'Respiration in Plants', 12, '11', 4, 'Plant Physiology', 6.0, 'critical', 'hard', ARRAY['c11-bio-9']::TEXT[], true, 'Cellular respiration: Glycolysis (EMP pathway), fermentation, TCA cycle (Krebs cycle), electron transport system (ETS) and oxidative phosphorylation, respiratory balance sheet, amphibolic pathway, respiratory quotient (RQ).'),
  ('c11-bio-13', 'cbse-11-biology', 'Plant Growth and Development', 13, '11', 4, 'Plant Physiology', 5.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Growth phases, growth rate, conditions for growth, differentiation, dedifferentiation and redifferentiation, development, plant growth regulators (auxins, gibberellins, cytokinins, ethylene, ABA).'),
  ('c11-bio-14', 'cbse-11-biology', 'Breathing and Exchange of Gases', 14, '11', 5, 'Human Physiology', 5.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Respiratory organs in animals, human respiratory system, mechanism of breathing and its regulation, respiratory volumes and capacities, transport of gases (oxygen and carbon dioxide dissociation curves), disorders of respiratory system.'),
  ('c11-bio-15', 'cbse-11-biology', 'Body Fluids and Circulation', 15, '11', 5, 'Human Physiology', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Composition of blood, blood groups (ABO, Rh), coagulation of blood, lymph, circulatory pathways, human circulatory system, cardiac cycle, cardiac output, ECG, double circulation, regulation of cardiac activity, disorders of circulatory system.'),
  ('c11-bio-16', 'cbse-11-biology', 'Excretory Products and their Elimination', 16, '11', 5, 'Human Physiology', 6.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Modes of excretion (Ammonotelism, Ureotelism, Uricotelism), human excretory system, structure of nephron, urine formation (glomerular filtration, reabsorption, secretion), counter current mechanism, regulation of kidney function (RAAS, ANF, ADH), micturition, dialysis.'),
  ('c11-bio-17', 'cbse-11-biology', 'Locomotion and Movement', 17, '11', 5, 'Human Physiology', 5.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Types of movement, muscle structure, contractile proteins (actin and myosin), mechanism of muscle contraction (sliding filament theory), skeletal system, joints, disorders of muscular and skeletal systems.'),
  ('c11-bio-18', 'cbse-11-biology', 'Neural Control and Coordination', 18, '11', 5, 'Human Physiology', 6.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Neuron as structural and functional unit of nervous system, generation and conduction of nerve impulse, synaptic transmission, central nervous system (brain and spinal cord), reflex action.'),
  ('c11-bio-19', 'cbse-11-biology', 'Chemical Coordination and Integration', 19, '11', 5, 'Human Physiology', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Endocrine glands and hormones; human endocrine system: hypothalamus, pituitary, pineal, thyroid, parathyroid, adrenal, pancreas, gonads; mechanism of hormone action (peptide vs steroid hormones).'),
  ('c11-cs-1', 'cbse-11-cs', 'Computer Systems and Organisation', 1, '11', 1, 'Computer Systems and Organisation', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Basic computer organisation: CPU, memory, hard disk, I/O devices, types of software, memory units, Boolean logic, number systems.'),
  ('c11-cs-2', 'cbse-11-cs', 'Computational Thinking and Programming - Python Basics', 2, '11', 2, 'Computational Thinking and Programming - 1', 8.0, 'critical', 'medium', ARRAY['c11-cs-1']::TEXT[], true, 'Introduction to Python, interactive and script mode, identifiers, keywords, data types, mutable and immutable, operators, conditionals and loops.'),
  ('c11-cs-3', 'cbse-11-cs', 'Strings, Lists, Tuples, and Dictionaries in Python', 3, '11', 2, 'Computational Thinking and Programming - 1', 9.0, 'critical', 'medium', ARRAY['c11-cs-2']::TEXT[], true, 'String operations and methods, List indexing, slicing, methods, Tuple creation and immutability, Dictionary key-value pairs and operations.'),
  ('c11-acc-1', 'cbse-11-accountancy', 'Introduction to Accounting', 1, '11', 1, 'Theoretical Framework', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Accounting- concept, meaning, as a source of information, objectives, advantages and limitations, types of accounting information; users of accounting information and their needs. Qualitative characteristics of accounting information. Role of accounting in business.'),
  ('c11-acc-2', 'cbse-11-accountancy', 'Theory Base of Accounting and Accounting Standards', 2, '11', 1, 'Theoretical Framework', 6.0, 'high', 'medium', ARRAY['c11-acc-1']::TEXT[], true, 'Fundamental accounting assumptions: GAAP, Business Entity, Money Measurement, Going Concern, Accounting Period, Cost Concept, Dual Aspect, Revenue Recognition, Matching, Full Disclosure, Consistency, Conservatism, Materiality.'),
  ('c11-acc-3', 'cbse-11-accountancy', 'Recording of Business Transactions - Journal & Ledger', 3, '11', 2, 'Accounting Process', 9.0, 'critical', 'hard', ARRAY['c11-acc-2']::TEXT[], true, 'Accounting Equation: Assets = Liabilities + Capital. Rules of debit and credit. Origin of transactions- source documents/Voucher. Books of Original Entry- Journal, Cash Book, Purchases Book, Sales Book, Ledger posting.'),
  ('c11-bst-1', 'cbse-11-bst', 'Nature and Purpose of Business', 1, '11', 1, 'Foundations of Business', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Concept of business, characteristics of business, comparison of business, profession and employment, classification of business activities - Industry and Commerce, business risk.'),
  ('c11-bst-2', 'cbse-11-bst', 'Forms of Business Organisations', 2, '11', 1, 'Foundations of Business', 7.0, 'critical', 'medium', ARRAY['c11-bst-1']::TEXT[], true, 'Sole Proprietorship, Joint Hindu Family Business, Partnership, Cooperative Societies, Joint Stock Company - concepts, merits, and limitations.'),
  ('c11-hist-1', 'cbse-11-history', 'Writing and City Life (Mesopotamia)', 1, '11', 1, 'Early Societies', 6.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Mesopotamia geography, growth of cities, development of writing, temples and trade, urbanization in southern Mesopotamia.'),
  ('c11-pol-1', 'cbse-11-polsci', 'Constitution: Why and How?', 1, '11', 1, 'Indian Constitution at Work', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Why do we need a Constitution? What does a constitution do? Who made the Indian constitution? Philosophy of the constitution.'),
  ('c11-pol-2', 'cbse-11-polsci', 'Rights, Election & Organs of Government', 2, '11', 1, 'Indian Constitution at Work', 7.0, 'critical', 'medium', ARRAY['c11-pol-1']::TEXT[], true, 'Fundamental Rights in Indian Constitution (Articles 14-32), Directive Principles of State Policy (DPSP), election systems (FPTP vs Proportional Representation), Election Commission of India, Parliamentary Executive, Bicameral Legislature, Independent Judiciary & Judicial Review.'),
  ('c11-pol-3', 'cbse-11-polsci', 'Political Theory: Freedom, Equality & Social Justice', 3, '11', 2, 'Political Theory', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'What is Politics? Meaning of Freedom: Negative vs Positive liberty, Harm Principle of John Stuart Mill. Equality: Significance of equality, dimensions of equality (political, economic, social), affirmative action. Social Justice: Rawls theory of justice (Veil of Ignorance), proportional justice, recognizing special needs.'),
  ('c11-hist-2', 'cbse-11-history', 'An Empire Across Three Continents (Roman Empire)', 2, '11', 2, 'Empires', 6.0, 'critical', 'medium', ARRAY['c11-hist-1']::TEXT[], true, 'The Roman Empire spanning Europe, North Africa and the Middle East; Senate, Emperor and Army; Principate founded by Augustus; Third century crisis; Gender, literacy and culture; Slavery and economic expansion; Late antiquity and Christianization under Constantine.'),
  ('c11-hist-3', 'cbse-11-history', 'Nomadic Empires, The Three Orders & Cultural Traditions', 3, '11', 3, 'Changing Traditions & Modernisation', 7.0, 'critical', 'medium', ARRAY['c11-hist-2']::TEXT[], true, 'Nomadic Empires: Genghis Khan and the Mongols, military organization (decimal system), Yasa legal code, trans-continental trade networks. The Three Orders: Feudal society in Western Europe (Clergy, Nobility, Peasantry), manorial estates, chivalry, Black Death crisis. Changing Cultural Traditions: Italian Renaissance, humanism (Petrarch), realism in art (Leonardo, Michelangelo), Copernicus scientific revolution.'),
  ('c11-eng-1', 'cbse-11-english', 'Hornbill Prose: "The Portrait of a Lady" & "We''re Not Afraid to Die"', 1, '11', 1, 'Hornbill: Prose & Poetry', 5.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'The Portrait of a Lady (Khushwant Singh): Loving portrait of grandmother, rosary beads, sparrow feeding, and silent mourning at death. We are Not Afraid to Die... If We Can All Be Together (Gordon Cook & Alan East): Epic seafaring survival voyage aboard Wavewalker across southern Indian Ocean storms, heroic fortitude of children Jonathan and Suzanne.'),
  ('c11-eng-2', 'cbse-11-english', 'Hornbill Prose & Poetry: "Discovering Tut", "The Laburnum Top" & "Voice of the Rain"', 2, '11', 1, 'Hornbill: Prose & Poetry', 5.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Discovering Tut: The Saga Continues (A.R. Williams): CT scan of Egyptian boy pharaoh Tutankhamun, Zahi Hawass forensic findings, Howard Carter 1922 discovery controversy. The Laburnum Top (Ted Hughes): Goldfinch bird transforming silent tree into engine of life. The Voice of the Rain (Walt Whitman): Cyclical poetic parallel between rain and music rising from the deep.'),
  ('c11-eng-3', 'cbse-11-english', 'Snapshots: "The Summer of the Beautiful White Horse" & "The Address"', 3, '11', 2, 'Snapshots (Supplementary Reader)', 5.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'The Summer of the Beautiful White Horse (William Saroyan): Garoghlanian Armenian tribe poverty, honesty reputation, Aram and Mourad riding stolen white horse, meeting John Byro, returning horse out of honor. The Address (Marga Minco): Post-WWII Holland, narrator visiting Mrs Dorling at 46 Marconi Street to retrieve mother antique belongings, emotional decision to forget address.'),
  ('c11-eng-4', 'cbse-11-english', 'Writing Skills & Grammar: Classified Ads, Posters, Speech & Debate', 4, '11', 3, 'Writing Skills & Grammar', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Classified Advertisements (Situation Vacant/Wanted, Sale/Purchase, To Let, Lost & Found), Poster designing on social and environmental causes, Speech Writing (formal introduction, problem analysis, inspirational conclusion), Debate Writing (Arguments for or against the motion), Integrated Grammar (Tenses, Clauses, Reordering).'),
  ('c11-eco-1', 'cbse-11-economics', 'Statistics for Economics: Collection, Organisation & Presentation of Data', 1, '11', 1, 'Part A: Statistics for Economics', 6.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'What is Economics? Meaning, scope and importance of statistics in economics. Collection of data: Sources (Primary vs Secondary), methods of collecting data (Census vs Sample surveys, NSSO, Census of India). Organisation of data: Variables (discrete, continuous), frequency distribution. Presentation of data: Tabular presentation and Diagrammatic presentation (Bar diagrams, Pie charts, Histograms, Ogives).'),
  ('c11-eco-2', 'cbse-11-economics', 'Statistical Tools: Central Tendency, Dispersion, Correlation & Index Numbers', 2, '11', 1, 'Part A: Statistics for Economics', 8.0, 'critical', 'hard', ARRAY['c11-eco-1']::TEXT[], true, 'Measures of Central Tendency: Arithmetic Mean (direct, shortcut, step-deviation methods), Median, and Mode. Correlation: Meaning, Scatter diagram, Karl Pearson coefficient of correlation (r), Spearman rank correlation. Index Numbers: Meaning, Laspeyres, Paasche, and Fisher ideal index number (satisfying Time Reversal and Factor Reversal tests), Wholesale Price Index (WPI), Consumer Price Index (CPI), and inflation calculation.'),
  ('c11-eco-3', 'cbse-11-economics', 'Introductory Microeconomics: Consumer Equilibrium & Demand', 3, '11', 2, 'Part B: Introductory Microeconomics', 8.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Introduction to Microeconomics: Economy, central problems of an economy (What, How, For whom to produce), Production Possibility Frontier (PPF) and Opportunity Cost. Consumer Equilibrium: Utility approach (Law of Diminishing Marginal Utility, single and two commodity cases: MU_x/P_x = MU_y/P_y), Indifference Curve approach (Indifference map, Marginal Rate of Substitution MRS, Budget line, tangency condition MRS_xy = P_x/P_y). Demand: Law of Demand, determinants, shifts vs movements along demand curve, Price Elasticity of Demand (percentage method, total outlay method).'),
  ('c11-eco-4', 'cbse-11-economics', 'Producer Behaviour, Supply & Forms of Market', 4, '11', 2, 'Part B: Introductory Microeconomics', 8.0, 'critical', 'hard', ARRAY['c11-eco-3']::TEXT[], true, 'Production Function: Short-Run and Long-Run, Total Product, Average Product, Marginal Product, Law of Variable Proportions (three stages: increasing, diminishing, negative returns). Cost: Short run costs (TFC, TVC, TC, AFC, AVC, ATC, MC - shapes and relationships). Revenue: TR, AR, MR relationships under perfect vs imperfect competition. Producer Equilibrium: MR = MC approach (MC must cut MR from below). Supply: Law of Supply, elasticity of supply. Perfect Competition: Features (large number of buyers and sellers, homogeneous product, free entry/exit, perfect knowledge, price taker firm P = AR = MR), determination of market price equilibrium, and shifts in demand and supply.'),
  ('c11-pe-1', 'cbse-11-pe', 'Changing Trends & Career in PE, Olympic Movement & Yoga', 1, '11', 1, 'Foundations of Physical Education & Olympism', 5.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Concept, Aims & Objectives of Physical Education; Changing Trends in Sports- playing surface, wearable gear and sports equipment, technological advancements; Career options in Physical Education. Olympic Movement: Ancient and Modern Olympics, Olympism Values (Excellence, Friendship, Respect), Olympic Symbols, Motto, Flag, Oath, International Olympic Committee (IOC) and Indian Olympic Association (IOA). Yoga: Meaning and Importance of Yoga, Introduction to Ashtanga Yoga (Yama, Niyama, Asana, Pranayama, Pratyahara, Dharana, Dhyana, Samadhi), Yogic Kriyas (Shatkarma).'),
  ('c11-pe-2', 'cbse-11-pe', 'Physical Fitness, Wellness, CWSN & Health Education', 2, '11', 2, 'Fitness, Inclusion & Health Science', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Physical Fitness, Wellness and Lifestyle: Meaning and Importance; Components of Physical Fitness (Cardiorespiratory Endurance, Muscular Strength, Muscular Endurance, Flexibility, Body Composition) and Skill-Related Fitness (Agility, Balance, Coordination, Power, Reaction Time, Speed). Physical Education & Sports for CWSN (Children with Special Needs): Concept of Disability & Disorder; Types of Disability (Cognitive, Intellectual, Physical); Paralympic Games, Special Olympics and Deaflympics. Health Education: Meaning, Importance and Principles of Health Education.'),
  ('c11-pe-3', 'cbse-11-pe', 'Physiology, Biomechanics, Psychology & Sports Training', 3, '11', 3, 'Anatomy, Kinesiology & Training Principles', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Fundamentals of Anatomy, Physiology and Kinesiology in Sports: Definition and Importance; Functions of Skeletal System, Classification of Bones and Types of Joints; Properties and Functions of Muscles; Structure and Functions of Circulatory System and Respiratory System. Fundamentals of Kinesiology and Biomechanics: Principles of Biomechanics, Types of Body Movements (Flexion, Extension, Abduction, Adduction, Rotation, Circumduction); Axis and Planes. Psychology & Sports: Definition & Importance; Adolescent Problems & their Management; Team Cohesion. Training & Doping in Sports: Concept & Principles of Sports Training (Overload, Specificity, Reversibility, Progression); Warming Up & Limbering Down; Concept of Doping and WADA banned substances.'),
  ('c11-acc-4', 'cbse-11-accountancy', 'Bank Reconciliation, Depreciation & Financial Statements', 4, '11', 2, 'Accounting Process & Financial Statements', 8.0, 'critical', 'hard', ARRAY['c11-acc-1']::TEXT[], true, 'Bank Reconciliation Statement (BRS): Need, reasons for difference between cash book and pass book balances, preparation with favorable/unfavorable balances. Depreciation, Provisions and Reserves: Straight Line Method (SLM) vs Written Down Value (WDV) method, accounting entries. Financial Statements of Sole Proprietorship: Trading Account, Profit and Loss Account, Balance Sheet with adjustments (closing stock, outstanding/prepaid expenses, accrued income, bad debts and provision for doubtful debts).'),
  ('c11-bst-3', 'cbse-11-bst', 'Business Finance, Small Business & Internal/International Trade', 3, '11', 2, 'Finance and Trade', 7.0, 'critical', 'medium', ARRAY['c11-bst-1']::TEXT[], true, 'Sources of Business Finance: Retained earnings, trade credit, factoring, lease financing, equity and preference shares, debentures, public deposits, loans from commercial banks and financial institutions, ADR, GDR, IDR. Small Business and Enterprises: Micro, Small and Medium Enterprises (MSMED Act 2006 criteria), role in rural industrialization, government schemes. Internal Trade: Wholesale and retail trade (departmental stores, chain stores, mail order houses), GST concept. International Business: Meaning, export and import procedure, documents used (Letter of Credit, Bill of Lading, Shipping Bill), role of WTO.'),
  ('c11-cs-4', 'cbse-11-cs', 'Society, Law and Ethics & Cyber Safety', 4, '11', 3, 'Unit 3: Society, Law and Ethics', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Digital Footprints, digital society and netizen (net etiquette, communication etiquette, social media etiquette). Data protection: Intellectual Property Rights (IPR - copyright, patent, trademark), open source software and licensing (Creative Commons, GPL, Apache). Cyber crime: definition, hacking, eavesdropping, phishing, cyber stalking, cyber trolling, ransomware, malware. Cyber safety: securely browsing the web, identity theft, passwords, confidential information, Indian Information Technology Act (IT Act 2000), e-waste management.'),
  ('c11-hin-aroh-1', 'cbse-11-hindi', 'प्रेमचंद - नमक का दारोगा (Aroh Chapter 1)', 1, '11', 1, 'आरोह भाग-1 (गद्य खंड)', 4.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'मुंशी प्रेमचंद की प्रसिद्ध यथार्थवादी कहानी जो ईमानदारी, कर्तव्यनिष्ठा और धर्म एवं धन के संघर्ष को चित्रित करती है।'),
  ('c11-hin-aroh-2', 'cbse-11-hindi', 'कृष्णा सोबती - मियाँ नसीरुद्दीन', 2, '11', 1, 'आरोह भाग-1 (गद्य खंड)', 4.0, 'medium', 'easy', ARRAY[]::TEXT[], true, 'खानदानी नानबाई मियाँ नसीरुद्दीन के व्यक्तित्व, रुचियों और खानदानी पाक कला का रोचक रेखाचित्र।'),
  ('c11-hin-aroh-3', 'cbse-11-hindi', 'सत्यजीत राय - अपू के साथ ढाई साल', 3, '11', 1, 'आरोह भाग-1 (गद्य खंड)', 4.0, 'medium', 'easy', ARRAY[]::TEXT[], true, 'फिल्म पाथेर पांचाली के निर्माण से जुड़े संस्मरण और कलात्मक संघर्ष की दास्तान।'),
  ('c11-hin-aroh-4', 'cbse-11-hindi', 'शेखर जोशी - गलता लोहा', 4, '11', 1, 'आरोह भाग-1 (गद्य खंड)', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'जातिगत भेदभाव और सामाजिक विसंगतियों पर गहरी चोट करती कहानी।'),
  ('c11-hin-aroh-5', 'cbse-11-hindi', 'मन्नू भंडारी - रजनी', 5, '11', 1, 'आरोह भाग-1 (गद्य खंड)', 4.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'शिक्षा के व्यवसायीकरण और ट्यूशन व्यवस्था के विरुद्ध संघर्ष करती महिला का प्रेरक नाटक।'),
  ('c11-hin-aroh-6', 'cbse-11-hindi', 'कबीर - पद (हम तौ एक एक करि जांनां)', 6, '11', 1, 'आरोह भाग-1 (काव्य खंड)', 3.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'कबीर की निर्गुण भक्ति और एकेश्वरवाद का उद्घोष।'),
  ('c11-hin-aroh-7', 'cbse-11-hindi', 'मीरा - पद (मेरे तो गिरधर गोपाल)', 7, '11', 1, 'आरोह भाग-1 (काव्य खंड)', 3.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'मीराबाई की अनन्य कृष्ण भक्ति और कुल की मर्यादा से परे समर्पण भाव।'),
  ('c11-hin-aroh-8', 'cbse-11-hindi', 'भवानी प्रसाद मिश्र - घर की याद', 8, '11', 1, 'आरोह भाग-1 (काव्य खंड)', 3.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'जेल प्रवास के दौरान कवि की पारिवारिक स्मृतियों और देशप्रेम का भावुक प्रकटीकरण।'),
  ('c11-hin-aroh-9', 'cbse-11-hindi', 'दुष्यंत कुमार - ग़ज़ल (साए में धूप)', 9, '11', 1, 'आरोह भाग-1 (काव्य खंड)', 3.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'समकालीन राजनीति और जनचेतना को झकझोरने वाली चुनिंदा ग़ज़लें।'),
  ('c11-hin-vit-1', 'cbse-11-hindi', 'कुमार गंधर्व - भारतीय गायिकाओं में बेजोड़: लता मंगेशकर', 10, '11', 2, 'वितान भाग-1', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'लता मंगेशकर के गायन की बारीकियों, शास्त्रीय संगीत एवं चित्रपट संगीत पर आधिकारिक लेख।'),
  ('c11-hin-vit-2', 'cbse-11-hindi', 'अनुपम मिश्र - राजस्थान की रजत बूंदें', 11, '11', 2, 'वितान भाग-1', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'मरुभूमि राजस्थान में वर्षा जल संचयन की पारंपरिक कुंई तकनीक का अद्भुत वर्णन।'),
  ('c11-hin-vit-3', 'cbse-11-hindi', 'बेबी हालदार - आलो-आंधारि', 12, '11', 2, 'वितान भाग-1', 4.0, 'medium', 'easy', ARRAY[]::TEXT[], true, 'घरेलू सहायिका से लेखिका बनने तक के जीवंत आत्मसंघर्ष की प्रेरक कथा।'),
  ('c11-hin-abh-1', 'cbse-11-hindi', 'अभिव्यक्ति और माध्यम: जनसंचार माध्यम एवं रचनात्मक लेखन', 13, '11', 3, 'अभिव्यक्ति और माध्यम', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'समाचार, संपादकीय, फीचर लेखन, नाटक एवं कथा लेखन के व्यावहारिक नियम।'),
  ('c11-ben-1', 'cbse-11-bengali', 'কর্তার ভূত (রবীন্দ্রনাথ ঠাকুর)', 1, '11', 1, 'সাহিত্য চর্চা (গল্প)', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'অন্ধ আনুগত্য ও কুসংস্কারাচ্ছন্ন মানসিকতার বিরুদ্ধে রবীন্দ্রনাথ ঠাকুরের রূপকধর্মী গল্প।'),
  ('c11-ben-2', 'cbse-11-bengali', 'তেলেনাপোতা আবিষ্কার (প্রেমেন্দ্র মিত্র)', 2, '11', 1, 'সাহিত্য চর্চা (গল্প)', 4.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'স্বপ্ন ও বাস্তবের মেলবন্ধনে প্রেমেন্দ্র মিত্রের অবিস্মরণীয় গল্প।'),
  ('c11-ben-3', 'cbse-11-bengali', 'নীলধ্বজের প্রতি জনা (মাইকেল মধুসূদন দত্ত)', 3, '11', 2, 'সাহিত্য চর্চা (কবিতা)', 5.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'বীরাঙ্গনা কাব্যের অন্তর্গত পুত্রের হত্যাকারীর সাথে সন্ধির প্রতিবাদে মাতার গর্জন।'),
  ('c11-ben-4', 'cbse-11-bengali', 'বাড়ির কাছে আরশিনগর (লালন শাহ)', 4, '11', 2, 'সাহিত্য চর্চা (কবিতা)', 3.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'বাউল সম্রাট লালন ফকিরের আত্মানুসন্ধান ও মরমি ভাবধারার গান।'),
  ('c11-ben-5', 'cbse-11-bengali', 'সুয়েজ খালে হাঙ্গর শিকার (স্বামী বিবেকানন্দ)', 5, '11', 1, 'সাহিত্য চর্চা (প্রবন্ধ)', 4.0, 'medium', 'easy', ARRAY[]::TEXT[], true, 'বিবেকানন্দের পরিব্রাজক গ্রন্থের অন্তর্গত সরস ও তথ্যসমৃদ্ধ বর্ণনা।'),
  ('c11-ben-6', 'cbse-11-bengali', 'বিশাল ডানাওয়ালা এক থুথ্থুড়ে বুড়ো / শিক্ষার সার্কাস', 6, '11', 2, 'আন্তর্জাতিক সাহিত্য', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'মার্কেজের জাদু বাস্তবতার গল্প এবং আয়াপ্পা পানিকরের শিক্ষাব্যবস্থা সম্পর্কিত আধুনিক কবিতা।'),
  ('c11-ben-7', 'cbse-11-bengali', 'বাঙালি শিল্প সাহিত্য ও সংস্কৃতির ইতিহাস', 7, '11', 3, 'শিল্প ও সংস্কৃতি', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'প্রাচীন ও মধ্যযুগের বাংলা সাহিত্য এবং চারু ও কারুকলার ঐতিহাসিক বিবর্তন।'),
  ('c11-ben-8', 'cbse-11-bengali', 'বোধ পরীক্ষণ ও বাংলা ব্যাকরণ (ধ্বনি পরিবর্তন ও প্রত্যয়)', 8, '11', 3, 'ব্যাকরণ ও নির্মিতি', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'অপিনিহিতি, অভিশ্রুতি, সমীভবন, স্বরসঙ্গতি, প্রত্যয় ও প্রবাদ-প্রবচনের প্রামাণ্য প্রয়োগ।'),
  ('c12-phy-1', 'cbse-12-physics', 'Electric Charges and Fields', 1, '12', 1, 'Electrostatics', 8.0, 'critical', 'hard', ARRAY['phy-vectors', 'phy-laws']::TEXT[], true, 'Electric charges, Conservation of charge, Coulomb law-force between two-point charges, forces between multiple charges; superposition principle and continuous charge distribution. Electric field, electric field due to a point charge, electric field lines, electric dipole, electric field due to a dipole, torque on a dipole in uniform electric field. Electric flux, statement of Gauss theorem and its applications to find field due to infinitely long straight wire, uniformly charged infinite plane sheet and uniformly charged thin spherical shell.'),
  ('c12-phy-2', 'cbse-12-physics', 'Electrostatic Potential and Capacitance', 2, '12', 1, 'Electrostatics', 8.0, 'critical', 'hard', ARRAY['c12-phy-1']::TEXT[], true, 'Electric potential, potential difference, electric potential due to a point charge, a dipole and system of charges; equipotential surfaces, electrical potential energy of a system of two-point charges and of electric dipole in an electrostatic field. Conductors and insulators, free charges and bound charges inside a conductor. Dielectrics and electric polarisation, capacitors and capacitance, combination of capacitors in series and in parallel, capacitance of a parallel plate capacitor with and without dielectric medium between the plates, energy stored in a capacitor.'),
  ('c12-phy-3', 'cbse-12-physics', 'Current Electricity', 3, '12', 2, 'Current Electricity', 8.0, 'critical', 'medium', ARRAY['c10-sci-11']::TEXT[], true, 'Electric current, flow of electric charges in a metallic conductor, drift velocity, mobility and their relation with electric current; Ohm law, electrical resistance, V-I characteristics (linear and non-linear), electrical energy and power, electrical resistivity and conductivity, temperature dependence of resistance. Internal resistance of a cell, potential difference and emf of a cell, combination of cells in series and in parallel, Kirchhoff rules and simple applications, Wheatstone bridge.'),
  ('c12-phy-4', 'cbse-12-physics', 'Moving Charges and Magnetism', 4, '12', 3, 'Magnetic Effects of Current and Magnetism', 9.0, 'critical', 'hard', ARRAY['c12-phy-3']::TEXT[], true, 'Concept of magnetic field, Oersted experiment. Biot - Savart law and its application to current carrying circular loop. Ampere law and its applications to infinitely long straight wire. Straight solenoid. Force on a moving charge in uniform magnetic and electric fields. Force on a current-carrying conductor in a uniform magnetic field. Force between two parallel current-carrying conductors-definition of ampere. Torque experienced by a current loop in uniform magnetic field; Current loop as a magnetic dipole and its magnetic dipole moment. Moving coil galvanometer its current sensitivity and conversion to ammeter and voltmeter.'),
  ('c12-phy-6', 'cbse-12-physics', 'Electromagnetic Induction', 6, '12', 4, 'Electromagnetic Induction and Alternating Currents', 6.0, 'high', 'medium', ARRAY['c12-phy-4']::TEXT[], true, 'Electromagnetic induction; Faraday laws, induced EMF and current; Lenz Law, Eddy currents. Self and mutual induction.'),
  ('c12-phy-7', 'cbse-12-physics', 'Alternating Current', 7, '12', 4, 'Electromagnetic Induction and Alternating Currents', 7.0, 'critical', 'hard', ARRAY['c12-phy-6']::TEXT[], true, 'Alternating currents, peak and RMS value of alternating current/voltage; reactance and impedance; LCR series circuit, resonance; power in AC circuits, wattless current. AC generator and transformer.'),
  ('c12-phy-9', 'cbse-12-physics', 'Ray Optics and Optical Instruments', 9, '12', 5, 'Optics', 9.0, 'critical', 'hard', ARRAY['c10-sci-9']::TEXT[], true, 'Refraction of light, total internal reflection and its optical applications, optical fibres, refraction at spherical surfaces, lenses, thin lens formula, lensmaker formula, magnification, power of a lens, combination of thin lenses in contact, refraction of light through a prism. Optical instruments: Microscopes and astronomical telescopes (reflecting and refracting) and their magnifying powers.'),
  ('c12-phy-10', 'cbse-12-physics', 'Wave Optics', 10, '12', 5, 'Optics', 7.0, 'critical', 'hard', ARRAY['c12-phy-9']::TEXT[], true, 'Wave front and Huygens principle, reflection and refraction of plane wave at a plane surface using wave fronts. Proof of laws of reflection and refraction using Huygens principle. Interference, Young double slit experiment and expression for fringe width, coherent sources and sustained interference of light. Diffraction due to a single slit, width of central maximum.'),
  ('c12-phy-14', 'cbse-12-physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 14, '12', 7, 'Electronic Devices', 6.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Energy bands in conductors, semiconductors and insulators (qualitative ideas only) Intrinsic and extrinsic semiconductors- p and n type, p-n junction. Semiconductor diode - I-V characteristics in forward and reverse bias, application of junction diode as a rectifier.'),
  ('c12-chem-1', 'cbse-12-chemistry', 'Solutions', 1, '12', 1, 'Solutions', 8.0, 'critical', 'medium', ARRAY['chem-basic']::TEXT[], true, 'Types of solutions, expression of concentration of solutions of solids in liquids, solubility of gases in liquids, solid solutions, Raoult law, colligative properties - relative lowering of vapour pressure, elevation of boiling point, depression of freezing point, osmotic pressure, determination of molecular masses using colligative properties, abnormal molecular mass, Van''t Hoff factor.'),
  ('c12-chem-2', 'cbse-12-chemistry', 'Electrochemistry', 2, '12', 2, 'Electrochemistry', 8.0, 'critical', 'hard', ARRAY['chem-redox']::TEXT[], true, 'Redox reactions, EMF of a cell, standard electrode potential, Nernst equation and its application to chemical cells, Relation between Gibbs energy change and EMF of a cell, conductance in electrolytic solutions, specific and molar conductivity, variations of conductivity with concentration, Kohlrausch Law, electrolysis and law of electrolysis, dry cell-electrolytic cells and Galvanic cells, lead accumulator, fuel cells, corrosion.'),
  ('c12-chem-3', 'cbse-12-chemistry', 'Chemical Kinetics', 3, '12', 3, 'Chemical Kinetics', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Rate of a reaction (Average and instantaneous), factors affecting rate of reaction: concentration, temperature, catalyst; order and molecularity of a reaction, rate law and specific rate constant, integrated rate equations and half-life (only for zero and first order reactions), concept of collision theory, Arrhenius equation, activation energy.'),
  ('c12-chem-4', 'cbse-12-chemistry', 'The d- and f-Block Elements', 4, '12', 4, 'The d- and f-Block Elements', 7.0, 'high', 'medium', ARRAY['chem-periodic']::TEXT[], true, 'General introduction, electronic configuration, occurrence and characteristics of transition metals, general trends in properties of the first-row transition metals - metallic character, ionization enthalpy, oxidation states, ionic radii, colour, catalytic property, magnetic properties, interstitial compounds, alloy formation, preparation and properties of K2Cr2O7 and KMnO4. Lanthanoids - Electronic configuration, oxidation states, chemical reactivity and lanthanoid contraction.'),
  ('c12-chem-5', 'cbse-12-chemistry', 'Coordination Compounds', 5, '12', 5, 'Coordination Compounds', 8.0, 'critical', 'hard', ARRAY['c12-chem-4', 'chem-bonding']::TEXT[], true, 'Coordination compounds - Introduction, ligands, coordination number, colour, magnetic properties and shapes, IUPAC nomenclature of mononuclear coordination compounds. Bonding, Werner theory, VBT, and CFT; structure and stereoisomerism, importance of coordination compounds (in qualitative inclusion, extraction of metals and biological system).'),
  ('c12-chem-6', 'cbse-12-chemistry', 'Haloalkanes and Haloarenes', 6, '12', 6, 'Haloalkanes and Haloarenes', 7.0, 'critical', 'hard', ARRAY['chem-organic']::TEXT[], true, 'Haloalkanes: Nomenclature, nature of C-X bond, physical and chemical properties, optical rotation mechanism of substitution reactions. Haloarenes: Nature of C-X bond, substitution reactions (Directive influence of halogen in monosubstituted compounds only). Uses and environmental effects of - dichloromethane, trichloromethane, tetrachloromethane, iodoform, freons, DDT.'),
  ('c12-chem-8', 'cbse-12-chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 8, '12', 8, 'Aldehydes, Ketones and Carboxylic Acids', 9.0, 'critical', 'hard', ARRAY['chem-organic']::TEXT[], true, 'Aldehydes and Ketones: Nomenclature, nature of carbonyl group, methods of preparation, physical and chemical properties, mechanism of nucleophilic addition, reactivity of alpha hydrogen in aldehydes, uses. Carboxylic Acids: Nomenclature, acidic nature, methods of preparation, physical and chemical properties; uses.'),
  ('c12-math-1', 'cbse-12-mathematics', 'Relations and Functions', 1, '12', 1, 'Relations and Functions', 6.0, 'high', 'medium', ARRAY['math-relations']::TEXT[], true, 'Types of relations: reflexive, symmetric, transitive and equivalence relations. One to one and onto functions.'),
  ('c12-math-3', 'cbse-12-mathematics', 'Matrices', 3, '12', 2, 'Algebra', 6.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Concept, notation, order, equality, types of matrices, zero and identity matrix, transpose of a matrix, symmetric and skew symmetric matrices. Operation on matrices: Addition and multiplication and multiplication with a scalar. Simple properties of addition, multiplication and scalar multiplication. Non- commutativity of multiplication of matrices and existence of non-zero matrices whose product is the zero matrix. Invertible matrices and proof of the uniqueness of inverse.'),
  ('c12-math-4', 'cbse-12-mathematics', 'Determinants', 4, '12', 2, 'Algebra', 7.0, 'critical', 'medium', ARRAY['c12-math-3']::TEXT[], true, 'Determinant of a square matrix (up to 3 x 3 matrices), minors, co-factors and applications of determinants in finding the area of a triangle. Adjoint and inverse of a square matrix. Consistency, inconsistency and number of solutions of system of linear equations by examples, solving system of linear equations in two or three variables (having unique solution) using inverse of a matrix.'),
  ('c12-math-5', 'cbse-12-mathematics', 'Continuity and Differentiability', 5, '12', 3, 'Calculus', 8.0, 'critical', 'hard', ARRAY['math-limits']::TEXT[], true, 'Continuity and differentiability, chain rule, derivative of inverse trigonometric functions, derivative of implicit functions. Concept of exponential and logarithmic functions. Derivatives of logarithmic and exponential functions. Logarithmic differentiation, derivative of functions expressed in parametric forms. Second order derivatives.'),
  ('c12-math-6', 'cbse-12-mathematics', 'Application of Derivatives', 6, '12', 3, 'Calculus', 8.0, 'critical', 'hard', ARRAY['c12-math-5']::TEXT[], true, 'Applications of derivatives: rate of change of quantities, increasing/decreasing functions, maxima and minima (first derivative test motivated geometrically and second derivative test given as a provable tool). Simple problems (that illustrate basic principles and understanding of the subject as well as real-life situations).'),
  ('c12-math-7', 'cbse-12-mathematics', 'Integrals', 7, '12', 3, 'Calculus', 11.0, 'critical', 'hard', ARRAY['c12-math-5']::TEXT[], true, 'Integration as inverse process of differentiation. Integration of a variety of functions by substitution, by partial fractions and by parts, Evaluation of simple integrals of the specified standard types. Fundamental Theorem of Calculus. Basic properties of definite integrals and evaluation of definite integrals.'),
  ('c12-math-10', 'cbse-12-mathematics', 'Vector Algebra', 10, '12', 4, 'Vectors and Three-Dimensional Geometry', 7.0, 'high', 'medium', ARRAY['phy-motion-plane']::TEXT[], true, 'Vectors and scalars, magnitude and direction of a vector. Direction cosines and direction ratios of a vector. Types of vectors, position vector of a point, negative of a vector, components of a vector, addition of vectors, multiplication of a vector by a scalar, position vector of a point dividing a line segment in a given ratio. Definition, properties and application of scalar (dot) product of vectors, vector (cross) product of vectors.'),
  ('c12-math-11', 'cbse-12-mathematics', 'Three-dimensional Geometry', 11, '12', 4, 'Vectors and Three-Dimensional Geometry', 7.0, 'critical', 'hard', ARRAY['c12-math-10']::TEXT[], true, 'Direction cosines and direction ratios of a line joining two points. Cartesian equation and vector equation of a line, skew lines, shortest distance between two lines. Angle between two lines.'),
  ('c12-math-13', 'cbse-12-mathematics', 'Probability', 13, '12', 6, 'Probability', 7.0, 'critical', 'hard', ARRAY['math-probability']::TEXT[], true, 'Conditional probability, multiplication theorem on probability, independent events, total probability, Bayes theorem, Random variable and its probability distribution, mean of random variable.'),
  ('c12-math-2', 'cbse-12-mathematics', 'Inverse Trigonometric Functions', 2, '12', 1, 'Relations and Functions', 5.0, 'high', 'medium', ARRAY['c12-math-1']::TEXT[], true, 'Definition, range, domain, principal value branch. Graphs of inverse trigonometric functions and elementary properties.'),
  ('c12-math-8', 'cbse-12-mathematics', 'Application of Integrals', 8, '12', 3, 'Calculus', 6.0, 'high', 'medium', ARRAY['c12-math-7']::TEXT[], true, 'Applications in finding the area under simple curves, especially lines, parabolas; area of circles / ellipses (in standard form only).'),
  ('c12-math-9', 'cbse-12-mathematics', 'Differential Equations', 9, '12', 3, 'Calculus', 7.0, 'critical', 'hard', ARRAY['c12-math-7']::TEXT[], true, 'Definition, order and degree, general and particular solutions of a differential equation. Solution of differential equations by method of separation of variables, solutions of homogeneous differential equations of first order and first degree. Solutions of linear differential equation of the type: dy/dx + py = q and dx/dy + px = q.'),
  ('c12-math-12', 'cbse-12-mathematics', 'Linear Programming', 12, '12', 5, 'Linear Programming', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Introduction, related terminology such as constraints, objective function, optimization, graphical method of solution for problems in two variables, feasible and infeasible regions (bounded or unbounded), feasible and infeasible solutions, optimal feasible solutions (up to three non-trivial constraints).'),
  ('c12-phy-5', 'cbse-12-physics', 'Magnetism and Matter', 5, '12', 3, 'Magnetic Effects of Current and Magnetism', 5.0, 'medium', 'easy', ARRAY['c12-phy-4']::TEXT[], true, 'Bar magnet, magnetic field lines, torque on a magnetic dipole in uniform magnetic field; magnetic field intensity due to a magnetic dipole along its axis and perpendicular to its axis; magnetic properties of materials- Para-, dia- and ferromagnetic substances with examples, magnetization and magnetic intensity.'),
  ('c12-phy-8', 'cbse-12-physics', 'Electromagnetic Waves', 8, '12', 5, 'Electromagnetic Waves', 4.0, 'medium', 'easy', ARRAY['c12-phy-6']::TEXT[], true, 'Basic idea of displacement current, Electromagnetic waves, their characteristics, their transverse nature (qualitative ideas only). Electromagnetic spectrum (radio waves, microwaves, infrared, visible, ultraviolet, X-rays, gamma rays) including elementary facts about their uses.'),
  ('c12-phy-11', 'cbse-12-physics', 'Dual Nature of Radiation and Matter', 11, '12', 7, 'Dual Nature of Radiation and Matter', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Dual nature of radiation, Photoelectric effect, Hertz and Lenard observations; Einstein photoelectric equation-particle nature of light. Experimental study of photoelectric effect: effect of intensity, potential, and frequency on photoelectric current and stopping potential. Matter waves-wave nature of particles, de-Broglie relation.'),
  ('c12-phy-12', 'cbse-12-physics', 'Atoms', 12, '12', 8, 'Atoms and Nuclei', 5.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'Alpha-particle scattering experiment; Rutherford model of atom; Bohr model of hydrogen atom, postulates, expression for radius of nth possible orbit, velocity and energy of electron in nth orbit, hydrogen line spectra (Lyman, Balmer, Paschen, Brackett, Pfund series).'),
  ('c12-phy-13', 'cbse-12-physics', 'Nuclei', 13, '12', 8, 'Atoms and Nuclei', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Composition and size of nucleus, nuclear force (strong nuclear force characteristics), mass-energy relation, mass defect, binding energy per nucleon and its variation with mass number, nuclear fission and nuclear fusion.'),
  ('c12-chem-7', 'cbse-12-chemistry', 'Alcohols, Phenols and Ethers', 7, '12', 7, 'Organic Chemistry', 7.0, 'critical', 'hard', ARRAY['c12-chem-6']::TEXT[], true, 'Nomenclature, methods of preparation, physical and chemical properties of alcohols, phenols and ethers. Acidic nature of phenols, Kolbe reaction, Reimer-Tiemann reaction, Williamson ether synthesis, electrophilic aromatic substitution.'),
  ('c12-chem-9', 'cbse-12-chemistry', 'Amines', 9, '12', 8, 'Organic Chemistry', 6.0, 'critical', 'medium', ARRAY['c12-chem-8']::TEXT[], true, 'Nomenclature, classification, structure, basic character of amines. Methods of preparation (reduction of nitro, nitriles, amides, Gabriel phthalimide synthesis, Hoffmann bromamide degradation). Chemical reactions: Hinsberg test, carbylamine test, diazotization and reactions of benzene diazonium chloride.'),
  ('c12-chem-10', 'cbse-12-chemistry', 'Biomolecules', 10, '12', 9, 'Biomolecules', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Carbohydrates- Classification (aldoses and ketoses), monosaccharides (glucose and fructose), D-L configuration, oligosaccharides (sucrose, lactose, maltose), polysaccharides (starch, cellulose, glycogen); Proteins- Elementary idea of amino acids, peptide bond, polypeptides, proteins, structure of proteins - primary, secondary, tertiary, quaternary, denaturation of proteins; enzymes; Hormones; Vitamins- Classification and functions; Nucleic Acids: DNA and RNA, genetic code.'),
  ('c12-bio-1', 'cbse-12-biology', 'Sexual Reproduction in Flowering Plants', 1, '12', 1, 'Unit VI: Reproduction', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Flower structure; development of male and female gametophytes; pollination-types, agencies and examples; outbreeding devices; pollen-pistil interaction; double fertilization; post fertilization events- development of endosperm and embryo, development of seed and formation of fruit; special modes- apomixis, parthenocarpy, polyembryony.'),
  ('c12-bio-2', 'cbse-12-biology', 'Human Reproduction', 2, '12', 1, 'Unit VI: Reproduction', 7.0, 'critical', 'medium', ARRAY['c12-bio-1']::TEXT[], true, 'Male and female reproductive systems; microscopic anatomy of testis and ovary; gametogenesis- spermatogenesis & oogenesis; menstrual cycle; fertilisation, embryo development up to blastocyst formation, implantation; pregnancy and placenta formation; parturition; lactation.'),
  ('c12-bio-3', 'cbse-12-biology', 'Reproductive Health', 3, '12', 1, 'Unit VI: Reproduction', 5.0, 'high', 'easy', ARRAY['c12-bio-2']::TEXT[], true, 'Need for reproductive health and prevention of Sexually Transmitted Diseases (STDs); birth control - need and methods, contraception and medical termination of pregnancy (MTP); amniocentesis; infertility and assisted reproductive technologies - IVF, ZIFT, GIFT.'),
  ('c12-bio-4', 'cbse-12-biology', 'Principles of Inheritance and Variation', 4, '12', 2, 'Unit VII: Genetics and Evolution', 8.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Mendelian inheritance; deviations from Mendelism – incomplete dominance, co-dominance, multiple alleles and inheritance of blood groups, pleiotropy; elementary idea of polygenic inheritance; chromosome theory of inheritance; chromosomes and genes; sex determination - in humans, birds, honey bee; linkage and crossing over; sex linked inheritance - haemophilia, colour blindness; Mendelian disorders in humans - thalassemia, sickle-cell anaemia, phenylketonuria; chromosomal disorders in humans - Down syndrome, Turner syndrome and Klinefelter syndrome.'),
  ('c12-bio-5', 'cbse-12-biology', 'Molecular Basis of Inheritance', 5, '12', 2, 'Unit VII: Genetics and Evolution', 9.0, 'critical', 'hard', ARRAY['c12-bio-4']::TEXT[], true, 'Search for genetic material (Griffith transforming principle, Avery-MacLeod-McCarty, Hershey-Chase bacteriophage experiment) and DNA as genetic material; Structure of DNA and RNA; DNA packaging; DNA replication (Meselson-Stahl experiment); Central dogma; Transcription, genetic code, translation; Gene expression and regulation - lac Operon; Genome and Human Genome Project (HGP); DNA fingerprinting.'),
  ('c12-bio-6', 'cbse-12-biology', 'Evolution', 6, '12', 2, 'Unit VII: Genetics and Evolution', 6.0, 'high', 'medium', ARRAY['c12-bio-5']::TEXT[], true, 'Origin of life; biological evolution and evidences for biological evolution from paleontology, comparative anatomy, embryology and molecular evidence; Darwin contribution, modern synthetic theory of evolution; mechanism of evolution - variation (mutation and recombination) and natural selection with examples, types of natural selection; Gene flow and genetic drift; Hardy-Weinberg principle; adaptive radiation; human evolution.'),
  ('c12-bio-7', 'cbse-12-biology', 'Human Health and Disease', 7, '12', 3, 'Unit VIII: Biology in Human Welfare', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Pathogens; parasites causing human diseases (malaria, dengue, chikungunya, filariasis, ascariasis, typhoid, pneumonia, common cold, amoebiasis, ring worm) and their control; Basic concepts of immunology - vaccines; cancer, HIV and AIDS; Adolescence - drug and alcohol abuse.'),
  ('c12-bio-8', 'cbse-12-biology', 'Microbes in Human Welfare', 8, '12', 3, 'Unit VIII: Biology in Human Welfare', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Microbes in household food processing, industrial production, sewage treatment, energy generation and as biocontrol agents and biofertilisers. Antibiotics; production and judicious use.'),
  ('c12-bio-9', 'cbse-12-biology', 'Biotechnology: Principles and Processes', 9, '12', 4, 'Unit IX: Biotechnology', 7.0, 'critical', 'hard', ARRAY['c12-bio-5']::TEXT[], true, 'Genetic Engineering (Recombinant DNA Technology). Tools of recombinant DNA technology: Restriction enzymes (EcoRI palindromic recognition), polymerases, ligases, cloning vectors (pBR322 selectable markers ampR and tetR, insertional inactivation), competent host; Processes of recombinant DNA technology: Isolation of DNA, cutting, PCR amplification using Taq polymerase, insertion into host, bioreactors (stirred-tank), and downstream processing.'),
  ('c12-bio-10', 'cbse-12-biology', 'Biotechnology and its Applications', 10, '12', 4, 'Unit IX: Biotechnology', 6.0, 'critical', 'medium', ARRAY['c12-bio-9']::TEXT[], true, 'Application of biotechnology in health and agriculture: Human insulin and vaccine production, stem cell technology, gene therapy; genetically modified organisms - Bt crops (Bt cotton endotoxin mechanism); transgenic animals; biosafety issues, biopiracy and patents.'),
  ('c12-bio-11', 'cbse-12-biology', 'Organisms and Populations', 11, '12', 5, 'Unit X: Ecology and Environment', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Population interactions- mutualism, competition, predation, parasitism, commensalism, amensalism; population attributes- growth, birth rate and death rate, age distribution, exponential growth vs logistic growth (Verhulst-Pearl logistic growth equation dN/dt = rN(K-N)/K).'),
  ('c12-bio-12', 'cbse-12-biology', 'Ecosystem', 12, '12', 5, 'Unit X: Ecology and Environment', 5.0, 'high', 'easy', ARRAY['c12-bio-11']::TEXT[], true, 'Ecosystems: Patterns, components; productivity and decomposition; energy flow; pyramids of number, biomass, energy; ecological succession.'),
  ('c12-bio-13', 'cbse-12-biology', 'Biodiversity and Conservation', 13, '12', 5, 'Unit X: Ecology and Environment', 5.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'Concept of biodiversity; patterns of biodiversity (latitudinal gradient, species-area relationship S = CA^Z); importance of biodiversity; loss of biodiversity (The Evil Quartet); biodiversity conservation; hotspots, endangered organisms, extinction, Red Data Book, Sacred Groves, biosphere reserves, national parks, wildlife sanctuaries, in-situ vs ex-situ conservation.'),
  ('c12-cs-1', 'cbse-12-cs', 'Python Functions & Exception Handling', 1, '12', 1, 'Unit 1: Computational Thinking and Programming - 2', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'User defined functions, parameters and arguments, default parameters, positional parameters, function returning values, flow of execution, scope of variables (global vs local, LEGB rule). Exception handling: try, except, else, finally blocks.'),
  ('c12-cs-2', 'cbse-12-cs', 'Data File Handling in Python (Text, Binary & CSV)', 2, '12', 1, 'Unit 1: Computational Thinking and Programming - 2', 8.0, 'critical', 'hard', ARRAY['c12-cs-1']::TEXT[], true, 'Need for data files, types of files: text files, binary files, CSV files. Text file: open(), read(), readline(), readlines(), write(), writelines(), seek(), tell(), with statement. Binary file: pickle module (dump(), load()). CSV file: import csv, csv.reader(), csv.writer(), writerow(), writerows().'),
  ('c12-cs-3', 'cbse-12-cs', 'Data Structures: Stack Implementation in Python', 3, '12', 1, 'Unit 1: Computational Thinking and Programming - 2', 6.0, 'critical', 'medium', ARRAY['c12-cs-1']::TEXT[], true, 'Data structure definition, linear vs non-linear structures. Stack: LIFO (Last In First Out) principle, operations on stack (Push and Pop) using a Python list, peek, display, overflow and underflow conditions.'),
  ('c12-cs-4', 'cbse-12-cs', 'Computer Networks', 4, '12', 2, 'Unit 2: Computer Networks', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Evolution of networking (ARPANET, NSFNET, Internet). Transmission media (Twisted pair, Coaxial, Optical Fiber, Infrared, Radio waves, Microwave, Satellite). Network devices (Modem, RJ45, Repeater, Hub, Switch, Gateway, Router, Access Point). Network topologies (Star, Bus, Tree). Network types (PAN, LAN, MAN, WAN). Protocols (HTTP, HTTPS, FTP, TCP/IP, POP3, SMTP, VoIP). Web services (WWW, HTML, XML, Web servers, Hosting). Network security (Firewall, Malware, Cookies, Phishing). 8-mark campus networking case study layout problem.'),
  ('c12-cs-5', 'cbse-12-cs', 'Database Management & SQL Interface with Python', 5, '12', 3, 'Unit 3: Database Management', 8.0, 'critical', 'medium', ARRAY['c12-cs-1']::TEXT[], true, 'Relational data model: Relation, attribute, tuple, degree, cardinality, keys (Candidate, Primary, Alternate, Foreign key). Structured Query Language (SQL): DDL commands (CREATE, DROP, ALTER), DML commands (SELECT, INSERT, UPDATE, DELETE). SQL clauses: WHERE, ORDER BY, GROUP BY, HAVING. Aggregate functions: MAX(), MIN(), AVG(), SUM(), COUNT(). Equi-join and natural join of two tables. Python-SQL connectivity: mysql.connector module, connect(), cursor(), execute(), fetchone(), fetchall(), commit().'),
  ('c12-eng-1', 'cbse-12-english', 'Flamingo Prose: "The Last Lesson" (Alphonse Daudet) & "Lost Spring"', 1, '12', 1, 'Unit 1: Flamingo - Literature', 4.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'The Last Lesson: Franco-Prussian war, linguistic chauvinism, M. Hamel final French lesson in Alsace school, "Vive La France!". Lost Spring (Anees Jung): Grinding poverty of ragpickers in Seemapuri (Saheb-e-Alam) and glass-bangle makers of Firozabad (Mukesh), caught in vicious web of sahukars and police.'),
  ('c12-eng-2', 'cbse-12-english', 'Flamingo Prose: "Deep Water" & "The Rattrap"', 2, '12', 1, 'Unit 1: Flamingo - Literature', 5.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Deep Water (William Douglas): Overcoming childhood water phobia and near-drowning at YMCA pool through disciplined determination. The Rattrap (Selma Lagerlof): Vagabond philosopher seeing the world as a giant rattrap with bait; transformation of the peddler through Edla Willmansson unconditional compassion.'),
  ('c12-eng-3', 'cbse-12-english', 'Flamingo Prose: "Indigo" & "Going Places"', 3, '12', 1, 'Unit 1: Flamingo - Literature', 4.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Indigo (Louis Fischer): Mahatma Gandhi Champaran satyagraha on behalf of sharecroppers against British planters, self-reliance, and civil disobedience turning point. Going Places (A.R. Barton): Adolescent hero-worship and fantasies of Sophie daydreaming about Irish football star Danny Casey vs realistic friend Jansie.'),
  ('c12-eng-4', 'cbse-12-english', 'Flamingo Poetry: "My Mother at Sixty-six", "Keeping Quiet" & "A Thing of Beauty"', 4, '12', 2, 'Unit 2: Flamingo - Poetry', 4.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'My Mother at Sixty-six (Kamala Das): Ageing, ache of separation, ashen winter moon simile. Keeping Quiet (Pablo Neruda): Counting to twelve, quiet introspection, cessation of war and whale hunting, life as quiet earth renewal. A Thing of Beauty (John Keats): Endless fountain of immortal joy dispelling pall from dark spirits.'),
  ('c12-eng-5', 'cbse-12-english', 'Vistas Supplementary: "The Third Level", "The Tiger King" & "The Enemy"', 5, '12', 3, 'Unit 3: Vistas (Supplementary)', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'The Third Level (Jack Finney): Charley psychological escape into 1894 Galesburg from modern insecurity. The Tiger King (Kalki): Satire on political arrogance, Maharaja killing 99 tigers, fatal prophecy fulfilled by wooden toy tiger. The Enemy (Pearl S. Buck): Dr Sadao Hoki ethical conflict between medical humanitarian duty and national loyalty treating wounded American POW.'),
  ('c12-eng-6', 'cbse-12-english', 'Advanced Writing Skills: Notices, Formal Invitations, Letters & Articles', 6, '12', 4, 'Unit 4: Advanced Writing Skills', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Notice writing (50 words, box format), Formal and Informal Invitations & Replies, Letter to the Editor on pressing national/civic issues, Application for a Job with Biodata/Resume, Article Writing and Report Writing for school magazines and newspapers.'),
  ('c12-eco-1', 'cbse-12-economics', 'National Income and Related Aggregates', 1, '12', 1, 'Part A: Introductory Macroeconomics', 8.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Macroeconomics: meaning. Basic concepts in macroeconomics: consumption goods, capital goods, final goods, intermediate goods; stocks and flows; gross investment and depreciation. Circular flow of income (two sector model); Methods of calculating National Income - Value Added or Production method, Expenditure method, Income method. Aggregates related to National Income: GNP, NNP, GDP and NDP at market price and at factor cost. Real and Nominal GDP. GDP and Welfare.'),
  ('c12-eco-2', 'cbse-12-economics', 'Money and Banking', 2, '12', 1, 'Part A: Introductory Macroeconomics', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Money – meaning and functions; supply of money - Currency held by the public and net demand deposits held by commercial banks. Money creation by the commercial banking system (credit multiplier = 1/LRR). Central bank and its functions (example of the Reserve Bank of India): Bank of issue, Govt Bank, Banker Bank, Control of Credit through Bank Rate, CRR, SLR, Repo Rate and Reverse Repo Rate, Open Market Operations, Margin requirement.'),
  ('c12-eco-3', 'cbse-12-economics', 'Determination of Income and Employment', 3, '12', 1, 'Part A: Introductory Macroeconomics', 8.0, 'critical', 'hard', ARRAY['c12-eco-1']::TEXT[], true, 'Aggregate demand and its components. Propensity to consume and propensity to save (average and marginal). Short-run equilibrium output; investment multiplier and its mechanism (k = 1/(1-MPC) = 1/MPS). Meaning of full employment and involuntary unemployment. Problems of excess demand and deficient demand; measures to correct them - changes in government spending, taxes and money supply.'),
  ('c12-eco-4', 'cbse-12-economics', 'Government Budget and the Economy & Balance of Payments', 4, '12', 1, 'Part A: Introductory Macroeconomics', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Government budget - meaning, objectives and components. Classification of receipts - revenue receipts and capital receipts; classification of expenditure – revenue expenditure and capital expenditure. Balanced, Surplus and Deficit Budget – measures of government deficit (Revenue, Fiscal, Primary Deficit). Balance of payments account - meaning and components (Current Account and Capital Account); Foreign exchange rate - fixed and flexible rates, managed floating.'),
  ('c12-eco-5', 'cbse-12-economics', 'Development Experience (1947-90) & Economic Reforms since 1991', 5, '12', 2, 'Part B: Indian Economic Development', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'A brief introduction of the state of Indian economy on the eve of independence. Common goals of Five Year Plans. Main features, problems and policies of agriculture (institutional aspects and new agricultural strategy, etc.), industry (IPR 1956; SSI – role & importance) and foreign trade. Economic Reforms since 1991: Features and appraisals of liberalisation, globalisation and privatisation (LPG policies); Concepts of demonetization and GST.'),
  ('c12-eco-6', 'cbse-12-economics', 'Current Challenges & Development Comparison with Neighbours', 6, '12', 2, 'Part B: Indian Economic Development', 7.0, 'critical', 'medium', ARRAY['c12-eco-5']::TEXT[], true, 'Human Capital Formation: How people become resource; Role of human capital in economic development; Growth of education sector in India. Rural development: Key issues - credit and marketing - role of cooperatives; agricultural diversification; alternative farming - organic farming. Employment: Growth and changes in work force participation rate in formal and informal sectors. Sustainable Economic Development: Meaning, effects of economic development on resources and environment. Comparative Development Experiences of India and its Neighbours: Trends in population, GDP, sectors, and Human Development Indicators (India, China and Pakistan).'),
  ('c12-bst-1', 'cbse-12-bst', 'Nature and Significance of Management & Principles of Management', 1, '12', 1, 'Part A: Principles and Functions of Management', 7.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Management - concept, objectives, and importance; Management as Science, Art and Profession; Levels of Management (Top, Middle, Supervisory); Management functions; Coordination - concept and characteristics ("essence of management"). Principles of Management - concept and significance; Fayol principles of management (14 principles); Taylor Scientific Management - principles and techniques (Functional Foremanship, Time Study, Motion Study, Fatigue Study, Differential Piece Wage System).'),
  ('c12-bst-2', 'cbse-12-bst', 'Business Environment, Planning & Organising', 2, '12', 1, 'Part A: Principles and Functions of Management', 8.0, 'critical', 'medium', ARRAY['c12-bst-1']::TEXT[], true, 'Business Environment: Dimensions (Economic, Social, Technological, Political, Legal). Planning: Meaning, features, limitations, planning process. Organising: Concept and importance, Organising Process; Structure of organisation - functional and divisional; Formal and informal organisation; Delegation: concept, elements (Authority, Responsibility, Accountability) and importance; Decentralisation: concept and importance.'),
  ('c12-bst-3', 'cbse-12-bst', 'Staffing, Directing & Controlling', 3, '12', 1, 'Part A: Principles and Functions of Management', 8.0, 'critical', 'medium', ARRAY['c12-bst-2']::TEXT[], true, 'Staffing: Concept and importance, staffing as part of HRM, staffing process, recruitment (internal vs external sources), selection process, training and development. Directing: Elements (Supervision, Motivation - Maslow hierarchy, Leadership - styles: Autocratic, Democratic, Laissez-faire, Communication - barriers and remedies). Controlling: Concept, relationship between planning and controlling, controlling process (Critical Point Control, Management by Exception).'),
  ('c12-bst-4', 'cbse-12-bst', 'Financial Management, Financial Markets & Marketing', 4, '12', 2, 'Part B: Business Finance and Marketing', 8.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Financial Management: Objectives (wealth maximization), financial decisions (Investment/Capital budgeting, Financing, Dividend decisions), capital structure (financial leverage trading on equity), fixed and working capital factors. Financial Markets: Money Market instruments vs Capital Market (Primary vs Secondary), Stock Exchange, NSE, BSE, SEBI functions (Regulatory, Development, Protective). Marketing Management: Marketing philosophies, Marketing Mix (4Ps: Product, Price, Place, Promotion). Consumer Protection: Consumer Protection Act 2019 rights and redressal agencies.'),
  ('c12-acc-1', 'cbse-12-accountancy', 'Accounting for Partnership: Fundamentals & Goodwill', 1, '12', 1, 'Part A: Accounting for Partnership Firms', 8.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Partnership: Features, Partnership Deed. Provisions of Indian Partnership Act 1932 in absence of deed. Fixed vs fluctuating capital accounts. Preparation of Profit and Loss Appropriation Account, division of profit. Past adjustments (relating to interest on capital, interest on drawing, salary, profit sharing ratio). Guarantee of profits. Goodwill: meaning, nature, factors affecting and methods of valuation - Average Profit, Super Profit and Capitalization.'),
  ('c12-acc-2', 'cbse-12-accountancy', 'Admission, Retirement and Dissolution of Partnership', 2, '12', 1, 'Part A: Accounting for Partnership Firms', 9.0, 'critical', 'hard', ARRAY['c12-acc-1']::TEXT[], true, 'Change in Profit Sharing Ratio: sacrificing ratio, gaining ratio. Admission of a partner: effect, treatment of goodwill (AS 26), revaluation of assets and reassessment of liabilities, treatment of reserves and accumulated profits, adjustment of capital accounts. Retirement and Death of a partner: calculation of gaining ratio, treatment of goodwill, deceased partner share of profit till date of death. Dissolution of a partnership firm: meaning, Realisation Account, preparation of Capital accounts and Cash/Bank account.'),
  ('c12-acc-3', 'cbse-12-accountancy', 'Accounting for Share Capital and Debentures', 3, '12', 2, 'Part B: Accounting for Companies', 9.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'Share and share capital: nature and types. Accounting for share capital: issue and allotment of equity and preference shares. Public subscription of shares - over subscription (pro-rata allotment) and under subscription; calls in advance and calls in arrears; issue of shares for consideration other than cash. Forfeiture of shares and Re-issue of forfeited shares; disclosure of share capital in company Balance Sheet. Debentures: Issue of debentures at par, at premium and at discount; Issue of debentures for consideration other than cash; Debentures as collateral security; Writing off discount/loss on issue of debentures.'),
  ('c12-acc-4', 'cbse-12-accountancy', 'Financial Statement Analysis & Cash Flow Statement', 4, '12', 3, 'Part C: Analysis of Financial Statements', 8.0, 'critical', 'hard', ARRAY['c12-acc-3']::TEXT[], true, 'Financial Statements of a Company: Balance Sheet and Statement of Profit and Loss in prescribed form with major headings and sub-headings (Schedule III to Companies Act 2013). Tools for Financial Statement Analysis: Comparative statements, Common size statements, Ratio analysis. Accounting Ratios: Liquidity ratios (Current, Quick); Solvency ratios (Debt-to-Equity, Total Assets to Debt, Proprietary, Interest Coverage); Activity ratios (Inventory Turnover, Trade Receivables Turnover, Trade Payables Turnover, Working Capital Turnover); Profitability ratios (Gross Profit, Operating, Net Profit, Return on Investment). Cash Flow Statement: Meaning, significance, preparation as per AS 3 (Revised) using indirect method.'),
  ('c12-his-1', 'cbse-12-history', 'Themes in Indian History Part I: Harappa, Early States & Thinkers', 1, '12', 1, 'Part I: Ancient India', 8.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Theme 1: Bricks, Beads and Bones - The Harappan Civilisation (Urban planning, Citadel, Great Bath, craft production, script, trade, Cunningham confusion). Theme 2: Kings, Farmers and Towns - Early States and Economies (600 BCE - 600 CE: Sixteen Mahajanapadas, Mauryan Empire, Ashoka inscriptions, land grants, numismatics). Theme 3: Kinship, Caste and Class - Early Societies (Mahabharata as dynamic text, caste, patriliny, gotra, gender). Theme 4: Thinkers, Beliefs and Buildings - Cultural Developments (Buddhism, Jainism, Sanchi Stupa preservation by Begums of Bhopal).'),
  ('c12-his-2', 'cbse-12-history', 'Themes in Indian History Part II: Travellers, Bhakti-Sufi & Vijayanagara', 2, '12', 2, 'Part II: Medieval India', 8.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Theme 5: Through the Eyes of Travellers (Al-Biruni Kitab-ul-Hind on caste and Sanskrit, Ibn Battuta Rihla on postal system and coconut, Francois Bernier on Mughal private property lack). Theme 6: Bhakti-Sufi Traditions (Alvars, Nayanars, Virashaiva movement of Basavanna, Mirabai, Kabir, Guru Nanak, Sufi Khanqahs and Chishti silsila). Theme 7: An Imperial Capital: Vijayanagara (14th to 16th century: Hampi, Krishna Deva Raya, Mahanavami Dibba, Royal Centre, Virupaksha temple). Theme 8: Peasants, Zamindars and the State (Agrarian society and Ain-i-Akbari of Abu l-Fazl).'),
  ('c12-his-3', 'cbse-12-history', 'Themes in Indian History Part III: Colonialism, 1857, Gandhi & Constitution', 3, '12', 3, 'Part III: Modern India', 9.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'Theme 9: Colonialism and the Countryside (Permanent Settlement of Bengal 1793, Sunset Law, Santhal rebellion under Sidhu and Kanhu, Deccan Riots 1875). Theme 10: Rebels and the Raj (1857 Revolt: Meerut outbreak, Bahadur Shah Zafar, visual representations and British vengeance). Theme 11: Mahatma Gandhi and the Nationalist Movement (Non-Cooperation, Salt Satyagraha, Quit India Movement, partition violence). Theme 12: Framing the Constitution (Constituent Assembly debates on language, federalism, minority rights, BR Ambedkar, Nehru Objectives Resolution).'),
  ('c12-pol-1', 'cbse-12-polsci', 'Contemporary World Politics: Bipolarity, Power Centres & Globalisation', 1, '12', 1, 'Part A: Contemporary World Politics', 8.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'The End of Bipolarity: Fall of Berlin Wall (1989), collapse of Soviet Union (USSR), Shock Therapy in post-communist regimes, consequences. Contemporary Centres of Power: European Union (EU), ASEAN, rise of China as economic power, BRICS, emerging powers (Japan, South Korea). Contemporary South Asia: Democratisation in Pakistan, Bangladesh, Nepal, Sri Lanka ethnic conflict, SAARC. International Organisations: United Nations restructure, UNSC veto reform, IMF, World Bank, WTO. Security in Contemporary World: Traditional vs Non-traditional security. Environment & Globalisation: Rio Summit, Kyoto Protocol, cultural and economic globalisation dimensions.'),
  ('c12-pol-2', 'cbse-12-polsci', 'Politics in India Since Independence: Nation-Building, Emergency & Coalition Era', 2, '12', 2, 'Part B: Politics in India Since Independence', 8.0, 'critical', 'medium', ARRAY['c12-pol-1']::TEXT[], true, 'Challenges of Nation-Building: Partition trauma, integration of princely states (Sardar Patel role, Kashmir, Hyderabad, Manipur), reorganisation of states (States Reorganisation Commission 1953). Era of One-Party Dominance: Congress dominance in first three general elections. Politics of Planned Development: Planning Commission, Five Year Plans, NITI Aayog. India External Relations: Non-Aligned Movement (NAM), Indo-China war 1962, Indo-Pak wars (1965, 1971), India nuclear policy. Challenges to and Restoration of Congress System: 1967 elections, Syndicate vs Indira Gandhi, 1971 grand victory. Crisis of Democratic Order: Declaration of Emergency (June 1975), JP movement, 1977 Janata Party victory. Regional Aspirations: Punjab crisis, Assam movement. Recent Developments: Coalition politics, Mandal Commission implementation, rise of BJP, economic reforms.'),
  ('c12-pe-1', 'cbse-12-pe', 'Management of Sporting Events & Children/Women in Sports', 1, '12', 1, 'Unit I & II: Sports Management and Inclusivity', 6.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Functions of Sports Events Management (Planning, Organising, Staffing, Directing & Controlling). Various Committees & their Responsibilities (pre; during & post). Tournaments - Knock-Out, League or Round Robin & Combination. Procedure to draw fixtures - Knock-Out (Bye & Seeding) & League (Staircase & Cyclic). Children & Women in Sports: Common postural deformities - Knock Knee, Flat Foot, Round Shoulders, Lordosis, Kyphosis, Bow Legs and Scoliosis and corrective exercises. Special consideration (Menarche & Menstrual Dysfunction). Female Athletes Triad (Osteoporosis, Amenorrhea, Eating Disorders).'),
  ('c12-pe-2', 'cbse-12-pe', 'Yoga, Nutrition, CWSN & Fitness Tests', 2, '12', 2, 'Unit III, IV, V, VI: Health, Nutrition & Testing', 6.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Yoga as Preventive measure for Lifestyle Disease (Obesity, Diabetes, Asthma, Hypertension) - Asanas procedure, benefits & contraindications. Physical Education & Sports for CWSN (Children with Special Needs - Divyang). Sports & Nutrition: Macro and Micro Nutrients, Balanced Diet, Nutritive & Non-Nutritive Components of Diet, Eating for Weight control, Pitfalls of Dieting, Food Intolerance, Food Myths. Test & Measurement in Sports: Fitness Test - SAI Khelo India Fitness Test in school; Rikli & Jones - Senior Citizen Fitness Test (Chair Stand Test, Arm Curl Test, Chair Sit & Reach, Back Scratch, 8 Foot Up and Go, 6 Minute Walk).'),
  ('c12-pe-3', 'cbse-12-pe', 'Physiology, Biomechanics, Psychology & Sports Training', 3, '12', 3, 'Unit VII, VIII, IX, X: Scientific Foundations of Sports', 6.0, 'critical', 'easy', ARRAY[]::TEXT[], true, 'Physiology & Injuries in Sports: Physiological factors determining components of physical fitness (Strength, Speed, Endurance, Flexibility), Effect of exercise on Cardiorespiratory System and Muscular System, Sports injuries: Classification (Soft Tissue: Abrasion, Contusion, Laceration, Incision, Sprain, Strain; Bone & Joint: Fractures, Dislocation), First Aid - PRICE treatment. Biomechanics & Sports: Newton laws of motion & their application in sports, Equilibrium (Dynamic & Static), Friction & Sports, Projectile in sports. Psychology & Sports: Personality types (Jung, Big Five theory), Motivation, Aggression in sports. Training in Sports: Talent Identification, Sports Training Cycle (Micro, Meso, Macro), Strength, Endurance, Speed, Flexibility development methods.'),
  ('c12-hin-aroh-1', 'cbse-12-hindi', 'हरिवंश राय बच्चन - आत्मपरिचय एवं एक गीत', 1, '12', 1, 'आरोह भाग-2 (काव्य खंड)', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'कवि का संसार के साथ द्वंद्वात्मक संबंध, जीवन-प्रेम और समय की गति का मार्मिक प्रकटीकरण।'),
  ('c12-hin-aroh-2', 'cbse-12-hindi', 'आलोक धन्वा - पतंग', 2, '12', 1, 'आरोह भाग-2 (काव्य खंड)', 3.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'बाल सुलभ इच्छाओं, उमंगों और शरद ऋतु की प्राकृतिक सुंदरता का बिंब-प्रधान चित्रण।'),
  ('c12-hin-aroh-3', 'cbse-12-hindi', 'कुँवर नारायण - कविता के बहाने / बात सीधी थी पर', 3, '12', 1, 'आरोह भाग-2 (काव्य खंड)', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'कविता की शाश्वत सामर्थ्य और भाषा के सहज सौंदर्य की प्रतिष्ठा।'),
  ('c12-hin-aroh-4', 'cbse-12-hindi', 'रघुवीर सहाय - कैमरे में बंद अपाहिज', 4, '12', 1, 'आरोह भाग-2 (काव्य खंड)', 3.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'दूरदर्शन और मीडिया की संवेदनहीनता पर तीखा व्यंग्य।'),
  ('c12-hin-aroh-5', 'cbse-12-hindi', 'तुलसीदास - कवितावली / लक्ष्मण मूर्च्छा और राम का विलाप', 5, '12', 1, 'आरोह भाग-2 (काव्य खंड)', 5.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'कलिकाल की विषमता और भ्रातृ-प्रेम का कारुणिक एवं भक्तिरस पूर्ण आख्यान।'),
  ('c12-hin-aroh-6', 'cbse-12-hindi', 'महादेवी वर्मा - भक्तिन', 6, '12', 1, 'आरोह भाग-2 (गद्य खंड)', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'महादेवी वर्मा की सेविका भक्तिन के स्वाभिमान, संघर्ष और ग्रामीण संस्कार का जीवंत रेखाचित्र।'),
  ('c12-hin-aroh-7', 'cbse-12-hindi', 'जैनेंद्र कुमार - बाज़ार दर्शन', 7, '12', 1, 'आरोह भाग-2 (गद्य खंड)', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'उपभोक्तावाद, बाज़ारूपन और भगत जी के संयमित जीवन दर्शन पर निबंध।'),
  ('c12-hin-aroh-8', 'cbse-12-hindi', 'धर्मवीर भारती - काले मेघा पानी दे', 8, '12', 1, 'आरोह भाग-2 (गद्य खंड)', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'वैज्ञानिक तर्क और लोक विश्वास (जीजी और इंद्रसेना) के द्वंद्व की संस्मरणात्मक प्रस्तुति।'),
  ('c12-hin-aroh-9', 'cbse-12-hindi', 'फणीश्वर नाथ रेणु - पहलवान की ढोलक', 9, '12', 1, 'आरोह भाग-2 (गद्य खंड)', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'महामारी और मृत्यु के हाहाकार के बीच अदम्य जिजीविषा और कला के महत्व की कथा।'),
  ('c12-hin-vit-1', 'cbse-12-hindi', 'मनोहर श्याम जोशी - सिल्वर वैडिंग', 10, '12', 2, 'वितान भाग-2', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'पीढ़ीगत अंतराल, बदलते आधुनिक मूल्य और यशोधर बाबू की पारंपरिक मानसिकता।'),
  ('c12-hin-vit-2', 'cbse-12-hindi', 'आनंद यादव - जूझ', 11, '12', 2, 'वितान भाग-2', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'पढ़ाई के लिए एक ग्रामीण किशोर के अथक संघर्ष और लगन की आत्मकथात्मक कहानी।'),
  ('c12-hin-vit-3', 'cbse-12-hindi', 'ओम थानवी - अतीत में दबे पाँव', 12, '12', 2, 'वितान भाग-2', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'सिंधु घाटी सभ्यता (मोहनजोदड़ो एवं हड़प्पा) के वास्तुशिल्प और सुव्यवस्थित नगर नियोजन की यात्रा।'),
  ('c12-hin-abh-1', 'cbse-12-hindi', 'अभिव्यक्ति और माध्यम: विभिन्न माध्यमों के लिए लेखन एवं पत्रकारीय प्रारूप', 13, '12', 3, 'अभिव्यक्ति और माध्यम', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'उल्टा पिरामिड शैली, छह ककार, विशेष लेखन, आलेख और विचारपरक लेखन।'),
  ('c12-ben-1', 'cbse-12-bengali', 'কে বাঁচায়, কে বাঁচে (মানিক বন্দ্যোপাধ্যায়)', 1, '12', 1, 'ছোটগল্প', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'তেতাল্লিশের মন্বন্তরের পটভূমিতে মৃত্যুঞ্জয়ের মানসিক বিপর্যয় ও মানবিক দায়বদ্ধতা।'),
  ('c12-ben-2', 'cbse-12-bengali', 'ভাত (মহাশ্বেতা দেবী)', 2, '12', 1, 'ছোটগল্প', 4.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'বঞ্চিত উৎসব নাইয়ার পেটের ভাতের জন্য আজীবন হাহাকার ও উচ্চবিত্তের শোষণ।'),
  ('c12-ben-3', 'cbse-12-bengali', 'ভারতবর্ষ (সৈয়দ মুস্তাফা সিরাজ)', 3, '12', 1, 'ছোটগল্প', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'ধর্মীয় সংকীর্ণতার ঊর্ধ্বে মানবিকতার জয়গান ও বুড়ি চরিত্রের প্রতীকী ব্যঞ্জনা।'),
  ('c12-ben-4', 'cbse-12-bengali', 'রূপনারায়ণের কূলে (রবীন্দ্রনাথ ঠাকুর)', 4, '12', 1, 'কবিতা', 4.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'শেষলেখা কাব্যের চরম উপলব্ধি: সত্য যে কঠিন, কঠিনেরে ভালোবাসিলাম।'),
  ('c12-ben-5', 'cbse-12-bengali', 'শিকার (জীবনানন্দ দাশ)', 5, '12', 1, 'কবিতা', 4.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'ভোরের নির্মল প্রাকৃতিক সৌন্দর্য ও নাগরিক সভ্যতার নৃশংস শিকারের রূপ।'),
  ('c12-ben-6', 'cbse-12-bengali', 'মহুয়ার দেশ (সমর সেন)', 6, '12', 1, 'কবিতা', 3.0, 'high', 'easy', ARRAY[]::TEXT[], true, 'ক্লান্ত নাগরিক জীবনে রোমান্টিক মহুয়া বনের স্বপ্ন ও কয়লাখনির নির্মম বাস্তবতা।'),
  ('c12-ben-7', 'cbse-12-bengali', 'নাটক: বিভাব (শম্ভু মিত্র) / নানা রঙের দিন (অজিতেশ বন্দ্যোপাধ্যায়)', 7, '12', 2, 'নাট্যসাহিত্য', 5.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'নবনাট্য আন্দোলন ও রজনীকান্ত চট্টোপাধ্যায়ের অভিনয় জীবনের করুণ ট্র্যাজেডি।'),
  ('c12-ben-8', 'cbse-12-bengali', 'সহায়ক গ্রন্থ: কোনি (মতি নন্দী)', 8, '12', 2, 'সহায়ক উপন্যাস', 6.0, 'critical', 'medium', ARRAY[]::TEXT[], true, 'ক্ষিদ্দা এবং দরিদ্র বস্তির মেয়ে কোনির জাতীয় স্তরে সাঁতারু হয়ে ওঠার অনুপ্রেরণাদায়ী কাহিনী।'),
  ('c12-ben-9', 'cbse-12-bengali', 'বাঙালি শিল্প সাহিত্য ও সংস্কৃতির ইতিহাস (চিত্রকলা, চলচ্চিত্র, বিজ্ঞান, ক্রীড়া)', 9, '12', 3, 'সংস্কৃতি চর্চা', 5.0, 'high', 'medium', ARRAY[]::TEXT[], true, 'সত্যজিৎ রায়, জগদীশচন্দ্র বসু, রামকিংকর বেইজ ও ভারতীয় ফুটবলে বাঙালির অবদান।'),
  ('c12-ben-10', 'cbse-12-bengali', 'ভাষাতত্ত্ব ও বাংলা ব্যাকরণ (রূপতত্ত্ব, বাক্যতত্ত্ব ও শব্দার্থতত্ত্ব)', 10, '12', 3, 'ভাষাতত্ত্ব', 4.0, 'critical', 'hard', ARRAY[]::TEXT[], true, 'রূপমূল, যুক্তধ্বনি, জটিল ও যৌগিক বাক্য বিশ্লেষণ এবং শব্দার্থ পরিবর্তনের ধারা।')
