INSERT INTO public.concepts (id, chapter_id, subject_id, code, title, description, key_concepts, key_formula, high_yield, in_cbse_syllabus, sequence_order)
VALUES
  ('phy-units-1', 'phy-units', 'cbse-11-physics', '2.1', 'SI Base & Supplementary Units', 'Radian and Steradian have units but no dimensions.', ARRAY['7 Base units: m, kg, s, A, K, mol, cd', 'Plane angle (rad) & Solid angle (sr) are dimensionless']::TEXT[], NULL, false, true, 1),
  ('phy-units-2', 'phy-units', 'cbse-11-physics', '2.2', 'Measurement of Large & Small Distances', '', ARRAY['Parallax method: b = D × θ', 'Estimation of molecular size using oleic acid']::TEXT[], 'θ = b / D', false, true, 2),
  ('phy-units-3', 'phy-units', 'cbse-11-physics', '2.3', 'Errors in Measurement (Absolute, Relative & %)', 'Errors ALWAYS add, never subtract, even in quotients or differences.', ARRAY['Systematic vs Random errors', 'Combination of errors in sums, differences, products, powers']::TEXT[], 'If Z = A^p B^q / C^r, ΔZ/Z = p(ΔA/A) + q(ΔB/B) + r(ΔC/C)', true, true, 3),
  ('phy-units-4', 'phy-units', 'cbse-11-physics', '2.4', 'Significant Figures & Rounding Off Rules', '', ARRAY['Rules for non-zero digits, leading/trailing zeros', 'Rules for addition/subtraction (decimal places) vs multiplication/division (sig figs)']::TEXT[], NULL, false, true, 4),
  ('phy-units-5', 'phy-units', 'cbse-11-physics', '2.5', 'Dimensions of Physical Quantities', '', ARRAY['Dimensional formulas of Force, Energy, Planck Constant, Gravitational Constant, Viscosity']::TEXT[], '[h] = [ML²T⁻¹], [G] = [M⁻¹L³T⁻²]', true, true, 5),
  ('phy-units-6', 'phy-units', 'cbse-11-physics', '2.6', 'Dimensional Analysis & Its Applications', 'Arguments of exponential, trigonometric, and logarithmic functions must be dimensionless.', ARRAY['Principle of homogeneity', 'Checking consistency of equations', 'Deriving relations & converting unit systems']::TEXT[], NULL, true, true, 6),
  ('phy-vectors-1', 'phy-vectors', 'cbse-11-physics', '3.1', 'Position, Distance & Displacement', '', ARRAY['Displacement is a vector, can be zero/negative', 'Distance ≥ |Displacement|']::TEXT[], NULL, false, true, 1),
  ('phy-vectors-2', 'phy-vectors', 'cbse-11-physics', '3.2', 'Average & Instantaneous Velocity and Speed', 'Average speed is NOT the magnitude of average velocity if the particle reverses direction.', ARRAY['v_avg = Total Displacement / Total Time', 'v(t) = dx/dt, Speed = |v|']::TEXT[], NULL, false, true, 2),
  ('phy-vectors-3', 'phy-vectors', 'cbse-11-physics', '3.3', 'Acceleration & Interpretation of x-t, v-t Graphs', '', ARRAY['Slope of x-t curve = velocity', 'Slope of v-t curve = acceleration', 'Area under v-t curve = displacement']::TEXT[], NULL, true, true, 3),
  ('phy-vectors-4', 'phy-vectors', 'cbse-11-physics', '3.4', 'Kinematic Equations for Uniform Acceleration', 'These formulas ONLY hold when acceleration is strictly constant.', ARRAY['Derivations using calculus & graphs', 'v = u + at', 's = ut + ½at²', 'v² = u² + 2as', 's_nth = u + a/2(2n - 1)']::TEXT[], 's_nth = u + rac{a}{2}(2n - 1)', true, true, 4),
  ('phy-vectors-5', 'phy-vectors', 'cbse-11-physics', '3.5', 'Motion Under Gravity & Free Fall', '', ARRAY['Sign convention for upward vs downward motion', 'Time of ascent = Time of descent', 'Max height H = u²/(2g)']::TEXT[], 'H_{max} = rac{u^2}{2g}, quad T = rac{2u}{g}', true, true, 5),
  ('phy-vectors-6', 'phy-vectors', 'cbse-11-physics', '3.6', 'Relative Velocity in One Dimension', '', ARRAY['v_{AB} = v_A - v_B', 'Trains crossing each other, overtaking scenarios']::TEXT[], NULL, true, true, 6),
  ('phy-motion-plane-1', 'phy-motion-plane', 'cbse-11-physics', '4.1', 'Vectors: Resolution & Triangle/Parallelogram Law', '', ARRAY['Resolution into orthogonal components: A_x = A cos θ, A_y = A sin θ', 'Resultant R = √(A² + B² + 2AB cos θ)']::TEXT[], 'R = sqrt{A^2 + B^2 + 2ABcos	heta}, quad 	analpha = rac{Bsin	heta}{A + Bcos	heta}', true, true, 1),
  ('phy-motion-plane-2', 'phy-motion-plane', 'cbse-11-physics', '4.2', 'Scalar (Dot) and Vector (Cross) Products', '', ARRAY['A · B = AB cos θ (Work, Power)', 'A × B = AB sin θ n̂ (Torque, Angular Momentum)', 'Determinant method for cross product']::TEXT[], NULL, true, true, 2),
  ('phy-motion-plane-3', 'phy-motion-plane', 'cbse-11-physics', '4.3', '2D Motion with Constant Acceleration', '', ARRAY['Independence of horizontal and vertical motions: x(t) and y(t) analyzed separately']::TEXT[], NULL, false, true, 3),
  ('phy-motion-plane-4', 'phy-motion-plane', 'cbse-11-physics', '4.4', 'Projectile Motion: Trajectory & Core Formulas', 'Range is the same for complementary angles θ and (90° - θ).', ARRAY['Parabolic path equation', 'Time of flight T = 2u sin θ / g', 'Max height H = u² sin² θ / (2g)', 'Range R = u² sin 2θ / g']::TEXT[], 'y = x	an	heta - rac{g x^2}{2u^2cos^2	heta}, quad R_{max} = rac{u^2}{g} 	ext{ at } 45^circ', true, true, 4),
  ('phy-motion-plane-5', 'phy-motion-plane', 'cbse-11-physics', '4.5', 'Horizontal & Inclined Plane Projectiles', '', ARRAY['Projectile fired horizontally from a tower: t = √(2h/g), R = u√(2h/g)', 'Range along an inclined plane']::TEXT[], NULL, false, true, 5),
  ('phy-motion-plane-6', 'phy-motion-plane', 'cbse-11-physics', '4.6', 'Uniform Circular Motion & Centripetal Acceleration', '', ARRAY['Magnitude of centripetal acceleration a_c = v²/r = ω²r directed toward center', 'Angular velocity ω = 2π/T = v/r']::TEXT[], 'a_c = rac{v^2}{r} = omega^2 r', true, true, 6),
  ('phy-laws-1', 'phy-laws', 'cbse-11-physics', '5.1', 'Newton''s First Law & Inertia', 'Pseudo force F_p = -m a_{frame} must ONLY be applied when working inside an accelerated frame.', ARRAY['Concept of force and inertia (rest, motion, direction)', 'Inertial vs Non-inertial frames & Pseudo force']::TEXT[], NULL, false, true, 1),
  ('phy-laws-2', 'phy-laws', 'cbse-11-physics', '5.2', 'Newton''s Second Law, Momentum & Impulse', '', ARRAY['F = dp/dt = m(dv/dt) + v(dm/dt)', 'Impulse J = ∫ F dt = Δp', 'Area under F-t curve = Impulse']::TEXT[], 'J = Delta p = F_{avg} Delta t', true, true, 2),
  ('phy-laws-3', 'phy-laws', 'cbse-11-physics', '5.3', 'Newton''s Third Law & Conservation of Momentum', '', ARRAY['Action and reaction act on DIFFERENT bodies, never cancel each other', 'Recoil of gun, rocket propulsion']::TEXT[], NULL, true, true, 3),
  ('phy-laws-4', 'phy-laws', 'cbse-11-physics', '5.4', 'Free Body Diagrams & Connected Bodies', '', ARRAY['Normal reaction, String tension, Pulley problems (Atwood machine)', 'Apparent weight in an accelerating lift']::TEXT[], 'a = rac{(m_2 - m_1)g}{m_1 + m_2}, quad T = rac{2m_1 m_2 g}{m_1 + m_2}', true, true, 4),
  ('phy-laws-5', 'phy-laws', 'cbse-11-physics', '5.5', 'Friction: Static, Limiting & Kinetic', 'Static friction is self-adjusting from 0 up to limiting friction μ_s N.', ARRAY['f_s ≤ μ_s N, f_k = μ_k N', 'Angle of friction & Angle of repose (tan θ = μ_s)', 'Block on an inclined plane']::TEXT[], NULL, true, true, 5),
  ('phy-laws-6', 'phy-laws', 'cbse-11-physics', '5.6', 'Dynamics of Circular Motion & Banking of Roads', '', ARRAY['Centripetal force provider (tension, friction, normal)', 'Optimum speed on banked road: v = √(rg tan θ)', 'Max safe speed with friction']::TEXT[], 'v_{opt} = sqrt{rg	an	heta}, quad v_{max} = sqrt{rgleft(rac{mu + 	an	heta}{1 - mu	an	heta}ight)}', true, true, 6),
  ('phy-work-1', 'phy-work', 'cbse-11-physics', '6.1', 'Work Done by Constant & Variable Force', '', ARRAY['W = F · s = F s cos θ', 'Work as area under F-x curve: W = ∫ F dx', 'Sign of work (positive, negative, zero)']::TEXT[], NULL, true, true, 1),
  ('phy-work-2', 'phy-work', 'cbse-11-physics', '6.2', 'Work-Energy Theorem', '', ARRAY['W_{net} = ΔK = K_f - K_i', 'Applies to both constant and variable forces, valid in all inertial frames']::TEXT[], 'W_{all} = K_f - K_i = rac{1}{2}m v_f^2 - rac{1}{2}m v_i^2', true, true, 2),
  ('phy-work-3', 'phy-work', 'cbse-11-physics', '6.3', 'Conservative Forces & Potential Energy', '', ARRAY['Work done in a closed path is zero', 'F = -dU/dx', 'Gravitational potential energy U = mgh', 'Spring potential energy U = ½kx²']::TEXT[], 'F = -rac{dU}{dx}, quad U_{spring} = rac{1}{2}kx^2', true, true, 3),
  ('phy-work-4', 'phy-work', 'cbse-11-physics', '6.4', 'Conservation of Mechanical Energy', 'For a string in vertical circle, string goes slack if v_{top} < √(gl). For a light rigid rod, v_{top} can be zero (v_{bottom} = √(4gl)).', ARRAY['ΔK + ΔU = 0 for conservative forces', 'Motion in a vertical circle (critical velocities: v_{bottom} = √(5gl), v_{top} = √(gl))']::TEXT[], NULL, true, true, 4),
  ('phy-work-5', 'phy-work', 'cbse-11-physics', '6.5', 'Power: Instantaneous & Average', '', ARRAY['P_{avg} = W / Δt', 'P_{inst} = F · v', '1 hp = 746 Watts']::TEXT[], 'P = ec{F} cdot ec{v}', false, true, 5),
  ('phy-work-6', 'phy-work', 'cbse-11-physics', '6.6', 'Collisions in 1D & 2D (Elastic vs Inelastic)', '', ARRAY['Coefficient of restitution e = (v_2 - v_1) / (u_1 - u_2)', 'e = 1 (Elastic), 0 < e < 1 (Inelastic), e = 0 (Perfectly Inelastic)', 'Loss of KE in inelastic collisions']::TEXT[], 'Delta K_{loss} = rac{1}{2}rac{m_1 m_2}{m_1 + m_2}(u_1 - u_2)^2(1 - e^2)', true, true, 6),
  ('phy-system-1', 'phy-system', 'cbse-11-physics', '7.1', 'Centre of Mass: Discrete & Continuous Systems', '', ARRAY['R_{CM} = Σ(m_i r_i) / Σm_i', 'Continuous bodies: X_{CM} = (1/M) ∫ x dm', 'CM of rod, ring, disc, hemisphere']::TEXT[], 'X_{CM} = rac{m_1 x_1 + m_2 x_2}{m_1 + m_2}', true, true, 1),
  ('phy-system-2', 'phy-system', 'cbse-11-physics', '7.2', 'Motion of Centre of Mass & Conservation of Linear Momentum', 'Internal forces (like explosion of a bomb or student walking on a boat) CANNOT shift the motion of the center of mass.', ARRAY['V_{CM} = P_{total} / M', 'F_{ext} = M a_{CM}', 'If F_{ext} = 0, CM moves with constant velocity or stays at rest']::TEXT[], NULL, true, true, 2),
  ('phy-system-3', 'phy-system', 'cbse-11-physics', '7.3', 'Vector Product of Two Vectors & Angular Velocity', '', ARRAY['Cross product properties: non-commutative A × B = - (B × A)', 'Relation v = ω × r']::TEXT[], NULL, false, true, 3),
  ('phy-system-4', 'phy-system', 'cbse-11-physics', '7.4', 'Centre of Gravity vs Centre of Mass', '', ARRAY['CG is where total gravitational torque vanishes', 'CG coincides with CM only in a uniform gravitational field']::TEXT[], NULL, false, true, 4),
  ('phy-gravity-1', 'phy-gravity', 'cbse-11-physics', '8.1', 'Kepler''s Laws of Planetary Motion', '', ARRAY['Law of orbits (ellipses with Sun at one focus)', 'Law of areas (dA/dt = L/(2m) is constant, angular momentum conservation)', 'Law of periods (T² ∝ a³)']::TEXT[], 'T^2 propto R^3, quad rac{dA}{dt} = rac{L}{2m}', true, true, 1),
  ('phy-gravity-2', 'phy-gravity', 'cbse-11-physics', '8.2', 'Universal Law of Gravitation & Constant G', '', ARRAY['F = G m_1 m_2 / r²', 'Vector form and Cavendish experiment for measuring G = 6.67 × 10⁻¹¹ N m²/kg²']::TEXT[], NULL, false, true, 2),
  ('phy-gravity-3', 'phy-gravity', 'cbse-11-physics', '8.3', 'Acceleration Due to Gravity (g) & Its Variations', 'At the center of Earth (d = R), g = 0.', ARRAY['g = GM / R²', 'Variation with height h: g_h = g(1 - 2h/R) for h << R', 'Variation with depth d: g_d = g(1 - d/R)', 'Variation with latitude due to Earth rotation: g'' = g - R ω² cos² λ']::TEXT[], 'g_h = gleft(1 - rac{2h}{R}ight), quad g_d = gleft(1 - rac{d}{R}ight)', true, true, 3),
  ('phy-gravity-4', 'phy-gravity', 'cbse-11-physics', '8.4', 'Gravitational Potential Energy & Gravitational Potential', '', ARRAY['Potential V = -GM / r', 'Potential Energy U = -GMm / r', 'Change in PE for height h: ΔU = mgh / (1 + h/R)']::TEXT[], 'U = -rac{GMm}{r}, quad V = -rac{GM}{r}', true, true, 4),
  ('phy-gravity-5', 'phy-gravity', 'cbse-11-physics', '8.5', 'Escape Velocity', '', ARRAY['Minimum speed to escape gravitational field: v_e = √(2GM/R) = √(2gR)', 'For Earth: v_e ≈ 11.2 km/s', 'Independent of mass and angle of projection']::TEXT[], 'v_e = sqrt{rac{2GM}{R}} = sqrt{2gR} approx 11.2	ext{ km/s}', true, true, 5),
  ('phy-gravity-6', 'phy-gravity', 'cbse-11-physics', '8.6', 'Earth Satellites & Orbital Velocity', '', ARRAY['Orbital speed v_o = √(GM/r)', 'Time period T = 2π √(r³/GM)', 'Total energy E = -GMm / (2r) = -K = U/2', 'Geostationary (T = 24h, h ≈ 36000 km) vs Polar satellites']::TEXT[], 'v_o = sqrt{rac{GM}{R+h}}, quad E_{total} = -rac{GMm}{2r} = -K = rac{U}{2}', true, true, 6),
  ('phy-solids-1', 'phy-solids', 'cbse-11-physics', '9.1', 'Stress, Strain & Hooke''s Law', '', ARRAY['Longitudinal, Volumetric, Shear stress and strain', 'Hooke''s law: Stress = E × Strain within elastic limit']::TEXT[], NULL, true, true, 1),
  ('phy-solids-2', 'phy-solids', 'cbse-11-physics', '9.2', 'Stress-Strain Curve & Material Behavior', 'Elastomers (like rubber) do NOT obey Hooke''s law and have high strain for small stress.', ARRAY['Proportional limit, Yield point, Breaking stress', 'Ductile vs Brittle materials vs Elastomers']::TEXT[], NULL, true, true, 2),
  ('phy-solids-3', 'phy-solids', 'cbse-11-physics', '9.3', 'Moduli of Elasticity (Young''s, Shear, Bulk)', '', ARRAY['Young''s modulus Y = (F/A) / (ΔL/L)', 'Shear modulus G = (F/A) / θ', 'Bulk modulus B = - ΔP / (ΔV/V)', 'Compressibility k = 1/B']::TEXT[], 'Y = rac{FL}{ADelta L}, quad B = -rac{VDelta P}{Delta V}', true, true, 3),
  ('phy-solids-4', 'phy-solids', 'cbse-11-physics', '9.4', 'Poisson''s Ratio (σ)', '', ARRAY['Lateral strain / Longitudinal strain', 'Theoretical range (-1 to 0.5), practical range (0 to 0.5)']::TEXT[], NULL, false, true, 4),
  ('phy-solids-5', 'phy-solids', 'cbse-11-physics', '9.5', 'Elastic Potential Energy in a Stretched Wire', '', ARRAY['U = ½ × Stress × Strain × Volume', 'Energy density u = ½ × Stress × Strain = ½ Y (Strain)²']::TEXT[], 'u = rac{1}{2}sigma epsilon = rac{1}{2}Yepsilon^2', true, true, 5),
  ('phy-fluids-1', 'phy-fluids', 'cbse-11-physics', '10.1', 'Pressure in a Fluid & Pascal''s Law', '', ARRAY['P = F/A', 'Variation of pressure with depth: P = P_0 + ρgh', 'Pascal''s law and hydraulic lift: F_1/A_1 = F_2/A_2']::TEXT[], NULL, true, true, 1),
  ('phy-fluids-2', 'phy-fluids', 'cbse-11-physics', '10.2', 'Streamline Flow & Equation of Continuity', '', ARRAY['Streamline vs turbulent flow', 'A_1 v_1 = A_2 v_2 (Conservation of mass for incompressible fluid)']::TEXT[], 'A_1 v_1 = A_2 v_2', true, true, 2),
  ('phy-fluids-3', 'phy-fluids', 'cbse-11-physics', '10.3', 'Bernoulli''s Principle & Applications', '', ARRAY['P + ½ρv² + ρgh = constant', 'Torricelli''s Law of Efflux: v = √(2gh)', 'Venturi-meter, Aerodynamic lift of aerofoil, Magnus effect']::TEXT[], 'P + rac{1}{2}ho v^2 + ho gh = 	ext{constant}', true, true, 3),
  ('phy-fluids-4', 'phy-fluids', 'cbse-11-physics', '10.4', 'Viscosity & Stokes'' Law', '', ARRAY['Newtonian viscous force F = -η A (dv/dx)', 'Stokes'' Law for spherical body: F_v = 6πηrv', 'Terminal velocity v_t = 2/9 r²(ρ - σ)g / η']::TEXT[], 'v_t = rac{2}{9}rac{r^2(ho - sigma)g}{eta}', true, true, 4),
  ('phy-fluids-5', 'phy-fluids', 'cbse-11-physics', '10.5', 'Surface Tension & Surface Energy', 'A soap bubble in air has TWO interfaces (inner and outer), so its excess pressure is 4T/R instead of 2T/R.', ARRAY['T = F / l = Work / ΔA', 'Angle of contact θ (<90° wetting, >90° non-wetting)', 'Excess pressure: ΔP = 2T/R (liquid drop), ΔP = 4T/R (soap bubble in air)']::TEXT[], 'Delta P_{drop} = rac{2T}{R}, quad Delta P_{bubble} = rac{4T}{R}', true, true, 5),
  ('phy-fluids-6', 'phy-fluids', 'cbse-11-physics', '10.6', 'Capillary Rise & Ascent Formula', '', ARRAY['Capillary rise h = (2T cos θ) / (r ρ g)', 'Weight of liquid column balanced by upward surface tension force']::TEXT[], 'h = rac{2Tcos	heta}{rho g}', true, true, 6),
  ('phy-thermal-1', 'phy-thermal', 'cbse-11-physics', '11.1', 'Thermal Expansion of Solids & Liquids', '', ARRAY['Linear expansion ΔL = L_0 α ΔT', 'Area expansion ΔA = A_0 β ΔT', 'Volume expansion ΔV = V_0 γ ΔT', 'Relation: α = β/2 = γ/3', 'Anomalous expansion of water between 0°C and 4°C']::TEXT[], NULL, true, true, 1),
  ('phy-thermal-2', 'phy-thermal', 'cbse-11-physics', '11.2', 'Specific Heat Capacity & Calorimetry', '', ARRAY['Q = m c ΔT', 'Principle of Calorimetry: Heat Lost = Heat Gained', 'Water equivalent of calorimeter']::TEXT[], NULL, true, true, 2),
  ('phy-thermal-3', 'phy-thermal', 'cbse-11-physics', '11.3', 'Change of State & Latent Heat', '', ARRAY['Q = m L', 'Latent heat of fusion of ice L_f = 80 cal/g', 'Latent heat of vaporization of water L_v = 540 cal/g', 'Regelation & Triple point of water (273.16 K, 0.006 atm)']::TEXT[], NULL, true, true, 3),
  ('phy-thermal-4', 'phy-thermal', 'cbse-11-physics', '11.4', 'Conduction, Convection & Radiation', '', ARRAY['Rate of heat flow dQ/dt = k A (T_1 - T_2) / L', 'Thermal resistance R_{th} = L / (kA)', 'Series and parallel combination of thermal conductors']::TEXT[], 'rac{dQ}{dt} = rac{kA(T_1 - T_2)}{L}', true, true, 4),
  ('phy-thermal-5', 'phy-thermal', 'cbse-11-physics', '11.5', 'Newton''s Law of Cooling, Wien''s Law & Stefan''s Law', '', ARRAY['Stefan-Boltzmann: E = e σ T⁴', 'Net loss to surroundings: E_{net} = e σ (T⁴ - T_0⁴)', 'Newton''s law of cooling: dT/dt = -K(T - T_0)', 'Wien''s displacement law: λ_{max} T = b = 2.898 × 10⁻³ m K']::TEXT[], 'lambda_{max} T = b, quad E = sigma T^4', true, true, 5),
  ('phy-thermo-1', 'phy-thermo', 'cbse-11-physics', '12.1', 'Zeroth Law & First Law of Thermodynamics', 'Be careful! In Physics ΔW = +PΔV (work by gas), whereas in Chemistry ΔW = -PΔV.', ARRAY['Zeroth law defines temperature', 'First law: ΔQ = ΔU + ΔW (Physics convention: ΔW done BY system is positive)', 'Internal energy is a state function U = n C_v T']::TEXT[], 'Delta Q = Delta U + Delta W, quad Delta W = int P dV', true, true, 1),
  ('phy-thermo-2', 'phy-thermo', 'cbse-11-physics', '12.2', 'Molar Specific Heat Capacities (Cp, Cv & Mayer''s Formula)', '', ARRAY['C_p - C_v = R', 'Adiabatic index γ = C_p / C_v = 1 + 2/f', 'Values of γ for monoatomic (5/3), diatomic (7/5), polyatomic (4/3)']::TEXT[], NULL, true, true, 2),
  ('phy-thermo-3', 'phy-thermo', 'cbse-11-physics', '12.3', 'Isothermal & Isochoric Processes', '', ARRAY['Isothermal: T constant, ΔU = 0, W = nRT ln(V_2/V_1) = Q', 'Isochoric: V constant, W = 0, Q = ΔU = n C_v ΔT']::TEXT[], NULL, true, true, 3),
  ('phy-thermo-4', 'phy-thermo', 'cbse-11-physics', '12.4', 'Adiabatic & Isobaric Processes', '', ARRAY['Adiabatic: Q = 0, PV^γ = constant, TV^{γ-1} = constant', 'Adiabatic work W = (P_1 V_1 - P_2 V_2)/(γ - 1) = -ΔU', 'Isobaric: P constant, W = PΔV = nRΔT, Q = n C_p ΔT']::TEXT[], 'PV^gamma = 	ext{const}, quad W_{adia} = rac{nR(T_1 - T_2)}{gamma - 1}', true, true, 4),
  ('phy-thermo-5', 'phy-thermo', 'cbse-11-physics', '12.5', 'Cyclic Processes & P-V Diagram Area', '', ARRAY['Net work done in cyclic process = Area enclosed by P-V loop', 'Clockwise cycle = positive work (heat engine)', 'Counter-clockwise = negative work (refrigerator)']::TEXT[], NULL, true, true, 5),
  ('phy-thermo-6', 'phy-thermo', 'cbse-11-physics', '12.6', 'Carnot Engine & Second Law of Thermodynamics', '', ARRAY['Kelvin-Planck statement & Clausius statement', 'Carnot cycle (2 isothermals + 2 adiabatics)', 'Efficiency η = 1 - Q_2/Q_1 = 1 - T_2/T_1', 'Coefficient of performance of refrigerator β = T_2 / (T_1 - T_2)']::TEXT[], 'eta = 1 - rac{T_2}{T_1}, quad eta = rac{T_2}{T_1 - T_2}', true, true, 6),
  ('phy-kinetic-1', 'phy-kinetic', 'cbse-11-physics', '13.1', 'Kinetic Gas Model & Pressure Formula', '', ARRAY['Assumptions of kinetic theory of gases', 'P = ⅓ ρ v_{rms}² = ⅓ (M/V) v_{rms}²', 'Average kinetic energy of gas: E = 3/2 nRT']::TEXT[], 'P = rac{1}{3}ho v_{rms}^2, quad v_{rms} = sqrt{rac{3RT}{M}}', true, true, 1),
  ('phy-kinetic-2', 'phy-kinetic', 'cbse-11-physics', '13.2', 'Molecular Speeds: RMS, Average & Most Probable', '', ARRAY['v_{rms} = √(3RT/M)', 'v_{avg} = √(8RT/πM)', 'v_{mp} = √(2RT/M)', 'Ratio: v_{mp} : v_{avg} : v_{rms} = √2 : √(8/π) : √3 ≈ 1 : 1.128 : 1.224']::TEXT[], 'v_{rms} = sqrt{rac{3RT}{M}}, quad v_{mp} = sqrt{rac{2RT}{M}}', true, true, 2),
  ('phy-kinetic-3', 'phy-kinetic', 'cbse-11-physics', '13.3', 'Degrees of Freedom & Equipartition of Energy', '', ARRAY['Law of equipartition: Energy per degree of freedom = ½ k_B T', 'Monoatomic: f = 3 (translational)', 'Diatomic: f = 5 (3 trans + 2 rot) at room temp, f = 7 with vibration', 'Total energy U = (f/2) nRT']::TEXT[], NULL, true, true, 3),
  ('phy-kinetic-4', 'phy-kinetic', 'cbse-11-physics', '13.4', 'Mean Free Path & Collision Frequency', '', ARRAY['Mean free path λ = 1 / (√2 π n d²)', 'Variation with pressure and temperature: λ ∝ T / P']::TEXT[], 'lambda = rac{1}{sqrt{2} n pi d^2}', false, true, 4),
  ('phy-oscillations-1', 'phy-oscillations', 'cbse-11-physics', '14.1', 'Simple Harmonic Motion (SHM) Kinematics', '', ARRAY['Displacement x(t) = A sin(ωt + φ)', 'Velocity v(t) = ω √(A² - x²)', 'Acceleration a(t) = - ω² x', 'Restoring force F = -kx']::TEXT[], 'a = -omega^2 x, quad v = omegasqrt{A^2 - x^2}', true, true, 1),
  ('phy-oscillations-2', 'phy-oscillations', 'cbse-11-physics', '14.2', 'Energy in Simple Harmonic Motion', 'At x = A/√2, Kinetic Energy equals Potential Energy.', ARRAY['Kinetic Energy K = ½ m ω² (A² - x²)', 'Potential Energy U = ½ k x² = ½ m ω² x²', 'Total Energy E = K + U = ½ m ω² A² = constant', 'Average K = Average U = ¼ m ω² A²']::TEXT[], 'E = rac{1}{2}momega^2 A^2 = rac{1}{2}kA^2', true, true, 2),
  ('phy-oscillations-3', 'phy-oscillations', 'cbse-11-physics', '14.3', 'Simple Pendulum & Angular SHM', '', ARRAY['T = 2π √(L/g) for small angular amplitudes', 'Independent of mass and amplitude', 'Seconds pendulum has T = 2 seconds (length ≈ 1 m)']::TEXT[], 'T = 2pisqrt{rac{L}{g}}', true, true, 3),
  ('phy-oscillations-4', 'phy-oscillations', 'cbse-11-physics', '14.4', 'Spring-Mass Systems (Series & Parallel)', '', ARRAY['T = 2π √(m/k)', 'Parallel springs: k_{eq} = k_1 + k_2', 'Series springs: 1/k_{eq} = 1/k_1 + 1/k_2', 'Cutting a spring into parts: k ∝ 1/L']::TEXT[], 'T = 2pisqrt{rac{m}{k_{eq}}}', true, true, 4),
  ('phy-oscillations-5', 'phy-oscillations', 'cbse-11-physics', '14.5', 'Damped & Forced Oscillations, Resonance', '', ARRAY['Damped SHM: x(t) = A e^{-bt/2m} cos(ω''t + φ)', 'Resonance condition: driving frequency equals natural frequency (amplitude peaks)']::TEXT[], NULL, false, true, 5),
  ('phy-waves-1', 'phy-waves', 'cbse-11-physics', '15.1', 'Progressive Wave Equation & Wave Speed', '', ARRAY['y(x, t) = A sin(kx - ωt + φ)', 'Wave number k = 2π/λ', 'Angular frequency ω = 2πν', 'Speed v = ω/k = ν λ', 'Speed of transverse wave on string: v = √(T/μ)']::TEXT[], 'v = sqrt{rac{T}{mu}}, quad y = Asin(kx - omega t)', true, true, 1),
  ('phy-waves-2', 'phy-waves', 'cbse-11-physics', '15.2', 'Speed of Sound & Newton-Laplace Formula', '', ARRAY['Newton''s isothermal assumption: v = √(P/ρ) (underestimated)', 'Laplace''s adiabatic correction: v = √(γP/ρ) = √(γRT/M)', 'Dependence on temperature: v ∝ √T']::TEXT[], 'v = sqrt{rac{gamma P}{ho}} = sqrt{rac{gamma RT}{M}}', true, true, 2),
