  ('c11-c2-t4', 'chem-structure', 'cbse-11-chemistry', '2.4', 'Aufbau principle, Pauli exclusion principle, Hund rule of maximum multiplicity, Cr & Cu configurations', '', ARRAY['Aufbau principle, Pauli exclusion principle, Hund rule of maximum multiplicity, Cr & Cu configurations']::TEXT[], NULL, true, true, 4),
  ('chem-periodic-1', 'chem-periodic', 'cbse-11-chemistry', '3.1', 'Modern Periodic Law & Periodic Table Architecture', '', ARRAY['Moseley''s law: √ν ∝ Z', 'Classification into s, p, d, f blocks based on valence subshell']::TEXT[], NULL, false, true, 1),
  ('chem-periodic-2', 'chem-periodic', 'cbse-11-chemistry', '3.2', 'Atomic & Ionic Radii Trends (Isoelectronic Species)', 'Among isoelectronic ions, the ion with the greatest positive nuclear charge Z has the smallest radius.', ARRAY['Covalent, Metallic, van der Waals radii (vdW > metallic > covalent)', 'Isoelectronic species radius ∝ 1/Z (e.g. Al³⁺ < Mg²⁺ < Na⁺ < F⁻ < O²⁻ < N³⁻)']::TEXT[], NULL, true, true, 2),
  ('chem-periodic-3', 'chem-periodic', 'cbse-11-chemistry', '3.3', 'Ionization Enthalpy & Electron Gain Enthalpy Trends', 'Chlorine has a MORE negative electron gain enthalpy than Fluorine!', ARRAY['IE exceptions: B < Be (Be has stable 2s²), O < N (N has half-filled 2p³)', 'Second IE is always greater than first IE', 'Electron gain enthalpy: Cl > F (due to small size of F and interelectronic repulsion in 2p), S > O']::TEXT[], NULL, true, true, 3),
  ('chem-periodic-4', 'chem-periodic', 'cbse-11-chemistry', '3.4', 'Electronegativity, Diagonal Relationship & Valence Trends', '', ARRAY['Pauling scale: F (4.0) > O (3.5) > N ≈ Cl (3.0)', 'Diagonal pairs: Li-Mg, Be-Al, B-Si due to similar charge/radius ratio']::TEXT[], NULL, true, true, 4),
  ('c11-c4-t1', 'chem-bonding', 'cbse-11-chemistry', '4.1', 'Lewis structures, formal charge, dipole moment and Fajan rules', '', ARRAY['Lewis structures, formal charge, dipole moment and Fajan rules']::TEXT[], NULL, true, true, 1),
  ('c11-c4-t2', 'chem-bonding', 'cbse-11-chemistry', '4.2', 'VSEPR theory geometry and shapes of molecules (NH3, H2O, SF4, ClF3, XeF4)', '', ARRAY['VSEPR theory geometry and shapes of molecules (NH3, H2O, SF4, ClF3, XeF4)']::TEXT[], NULL, true, true, 2),
  ('c11-c4-t3', 'chem-bonding', 'cbse-11-chemistry', '4.3', 'Hybridization: sp, sp2, sp3, sp3d, sp3d2 shapes and sigma/pi bonds', '', ARRAY['Hybridization: sp, sp2, sp3, sp3d, sp3d2 shapes and sigma/pi bonds']::TEXT[], NULL, true, true, 3),
  ('c11-c4-t4', 'chem-bonding', 'cbse-11-chemistry', '4.4', 'Molecular Orbital Theory (MOT): MO diagrams, bond order, magnetic properties of B2, C2, N2, O2', '', ARRAY['Molecular Orbital Theory (MOT): MO diagrams, bond order, magnetic properties of B2, C2, N2, O2']::TEXT[], NULL, true, true, 4),
  ('c11-c5-t1', 'chem-thermo', 'cbse-11-chemistry', '5.1', 'First law Delta U = q + w, Enthalpy Delta H = Delta U + Delta n_g RT', '', ARRAY['First law Delta U = q + w, Enthalpy Delta H = Delta U + Delta n_g RT']::TEXT[], NULL, true, true, 1),
  ('c11-c5-t2', 'chem-thermo', 'cbse-11-chemistry', '5.2', 'Hess''s Law of constant heat summation and standard enthalpies of reaction', '', ARRAY['Hess''s Law of constant heat summation and standard enthalpies of reaction']::TEXT[], NULL, true, true, 2),
  ('c11-c5-t3', 'chem-thermo', 'cbse-11-chemistry', '5.3', 'Entropy Delta S, Gibbs free energy Delta G = Delta H - T Delta S and spontaneity criteria', '', ARRAY['Entropy Delta S, Gibbs free energy Delta G = Delta H - T Delta S and spontaneity criteria']::TEXT[], NULL, true, true, 3),
  ('chem-equilibrium-1', 'chem-equilibrium', 'cbse-11-chemistry', '7.1', 'Law of Mass Action & Equilibrium Constants (Kc, Kp)', '', ARRAY['Relation: K_p = K_c (RT)^{Δn_g}', 'If Δn_g = 0, K_p = K_c and equilibrium is independent of pressure', 'Properties: reversing reaction inverts K, multiplying coefficients raises K to power']::TEXT[], 'K_p = K_c(RT)^{Delta n_g}', true, true, 1),
  ('chem-equilibrium-2', 'chem-equilibrium', 'cbse-11-chemistry', '7.2', 'Reaction Quotient (Q) & Le Chatelier''s Principle', 'Adding an inert gas at CONSTANT VOLUME does not shift the equilibrium at all!', ARRAY['Q < K (forward), Q > K (backward)', 'Effect of temperature: Endothermic shifts forward on heating, Exothermic shifts backward', 'Effect of pressure/volume: increase in P shifts towards fewer moles of gas', 'Inert gas addition at constant V has NO effect; at constant P shifts to more moles']::TEXT[], NULL, true, true, 2),
  ('chem-equilibrium-3', 'chem-equilibrium', 'cbse-11-chemistry', '7.3', 'Acids, Bases & pH Calculations', '', ARRAY['Arrhenius, Brønsted-Lowry (conjugate acid-base pairs), Lewis (electron pair acceptor/donor)', 'Ionic product of water K_w = [H⁺][OH⁻] = 10⁻¹⁴ at 298 K', 'pH = - log[H⁺], pH + pOH = 14', 'Weak acid ionization: [H⁺] = √(K_a C), pH = ½(pK_a - log C)']::TEXT[], 'pH = -log_{10}[H^+], quad [H^+] = sqrt{K_a C}', true, true, 3),
  ('chem-equilibrium-4', 'chem-equilibrium', 'cbse-11-chemistry', '7.4', 'Common Ion Effect & Salt Hydrolysis', '', ARRAY['Common ion suppresses ionization of weak electrolytes', 'Weak Acid + Strong Base salt: pH = 7 + ½(pK_a + log C)', 'Strong Acid + Weak Base salt: pH = 7 - ½(pK_b + log C)', 'Weak Acid + Weak Base salt: pH = 7 + ½(pK_a - pK_b)']::TEXT[], 'pH = 7 + rac{1}{2}(pK_a + log C) quad (	ext{WA + SB salt})', true, true, 4),
  ('chem-equilibrium-5', 'chem-equilibrium', 'cbse-11-chemistry', '7.5', 'Buffer Solutions & Henderson-Hasselbalch Equation', '', ARRAY['Acidic buffer (CH₃COOH + CH₃COONa): pH = pK_a + log([Salt]/[Acid])', 'Basic buffer (NH₄OH + NH₄Cl): pOH = pK_b + log([Salt]/[Base])', 'Buffer capacity is maximum when [Salt] = [Acid] (pH = pK_a)']::TEXT[], 'pH = pK_a + log_{10}left(rac{[	ext{Salt}]}{[	ext{Acid}]}ight)', true, true, 5),
  ('chem-equilibrium-6', 'chem-equilibrium', 'cbse-11-chemistry', '7.6', 'Solubility Product (Ksp) & Precipitation Condition', '', ARRAY['For A_x B_y ⇌ x A^{y+} + y B^{x-}, K_{sp} = x^x y^y S^{x+y}', 'Ionic product Q_{sp} vs K_{sp}: Q_{sp} > K_{sp} leads to precipitation', 'Applications in qualitative salt analysis (Group reagents)']::TEXT[], 'K_{sp} = [A^{y+}]^x [B^{x-}]^y', true, true, 6),
  ('chem-redox-1', 'chem-redox', 'cbse-11-chemistry', '8.1', 'Oxidation Number Calculation Rules & Exceptions', 'CrO₅ has two peroxide linkages (-O-O-), so its oxidation state is +6, never +10!', ARRAY['Rules for assigning oxidation numbers', 'Exceptions: CrO₅ (peroxide butterfly structure, Cr is +6 not +10), H₂SO₅ (Caro''s acid, S is +6), Fe₃O₄ (fractional +8/3)']::TEXT[], NULL, true, true, 1),
  ('chem-redox-2', 'chem-redox', 'cbse-11-chemistry', '8.2', 'Types of Redox Reactions', '', ARRAY['Combination, Decomposition, Displacement reactions', 'Disproportionation reactions (same element simultaneously oxidized and reduced, e.g. H₂O₂, Cl₂ + NaOH)']::TEXT[], NULL, false, true, 2),
  ('chem-redox-3', 'chem-redox', 'cbse-11-chemistry', '8.3', 'Balancing Redox: Ion-Electron Method (Half-Reaction)', '', ARRAY['Step-by-step balancing in acidic medium (balance O with H₂O, H with H⁺, charge with e⁻)', 'Balancing in basic medium (add OH⁻ equal to H⁺ to both sides)']::TEXT[], NULL, true, true, 3),
  ('chem-redox-4', 'chem-redox', 'cbse-11-chemistry', '8.4', 'Electrochemical Cells & Standard Electrode Potential', '', ARRAY['Daniell cell (Zn|Zn²⁺ || Cu²⁺|Cu)', 'E°_{cell} = E°_{cathode} - E°_{anode}', 'Electrochemical series: lower reduction potential means stronger reducing agent (Li is strongest reducing agent in aqueous medium)']::TEXT[], 'E^circ_{cell} = E^circ_{cathode} - E^circ_{anode}', true, true, 4),
  ('chem-organic-1', 'chem-organic', 'cbse-11-chemistry', '12.1', 'IUPAC Nomenclature of Organic Compounds', 'Carboxylic acid (-COOH) always takes highest priority (carbon #1) in IUPAC names.', ARRAY['Longest chain rule, lowest locant rule', 'Priority order of principal functional groups: -COOH > -SO₃H > -COOR > -COCl > -CONH₂ > -CN > -CHO > >C=O > -OH > -NH₂ > C=C > C≡C', 'Naming polyfunctional compounds and aromatic derivatives']::TEXT[], NULL, true, true, 1),
  ('chem-organic-2', 'chem-organic', 'cbse-11-chemistry', '12.2', 'Isomerism: Structural & Introduction to Stereoisomerism', '', ARRAY['Chain, Position, Functional, Metamerism, Tautomerism (Keto-Enol equilibrium)', 'Geometrical isomerism (cis-trans, conditions for restricted rotation)']::TEXT[], NULL, true, true, 2),
  ('chem-organic-3', 'chem-organic', 'cbse-11-chemistry', '12.3', 'Reaction Intermediates: Carbocations, Carbanions, Free Radicals', '', ARRAY['Homolytic vs Heterolytic fission', 'Carbocation stability: 3° > 2° > 1° > CH₃⁺ (hyperconjugation + inductive effect)', 'Carbanion stability: CH₃⁻ > 1° > 2° > 3°', 'Electrophiles vs Nucleophiles']::TEXT[], NULL, true, true, 3),
  ('chem-organic-4', 'chem-organic', 'cbse-11-chemistry', '12.4', 'Inductive (+I, -I) & Electromeric (E) Effects', '', ARRAY['Permanent polarization through σ bonds, diminishes with distance', '-I order: -NO₂ > -CN > -COOH > -F > -Cl > -Br > -I > -OH', '+I order: -C(CH₃)₃ > -CH(CH₃)₂ > -CH₂CH₃ > -CH₃', 'Acidity comparison of haloacetic acids']::TEXT[], NULL, true, true, 4),
  ('chem-organic-5', 'chem-organic', 'cbse-11-chemistry', '12.5', 'Resonance / Mesomeric (+M, -M) & Hyperconjugation', 'Halogens exhibit -I > +M (inductive dominates resonance for reactivity, but +M dictates ortho/para orientation).', ARRAY['Rules for writing resonance contributors & stability of resonating structures', '+M groups donate lone pair (OH, OR, NH₂, halogen)', '-M groups withdraw electrons (NO₂, CN, CHO, COOH)', 'Hyperconjugation (no-bond resonance): Baker-Nathan effect, depends on number of α-hydrogens']::TEXT[], NULL, true, true, 5),
  ('chem-organic-6', 'chem-organic', 'cbse-11-chemistry', '12.6', 'Purification & Quantitative Elemental Analysis', '', ARRAY['Crystallization, Sublimation, Distillation (Fractional, Steam, Vacuum)', 'Chromatography (Thin-Layer, Column)', 'Lassaigne''s test for N, S, Halogens', 'Dumas and Kjeldahl method for Nitrogen estimation', 'Carius method for Halogens and Sulfur']::TEXT[], NULL, false, true, 6),
  ('chem-hydrocarbons-1', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.1', 'Alkanes: Conformations & Free Radical Halogenation', '', ARRAY['Sawhorse and Newman projections of Ethane: Staggered is more stable than Eclipsed by 12.5 kJ/mol (torsional strain)', 'Wurtz reaction: 2 R-X + 2 Na → R-R (not suitable for odd carbon alkanes)', 'Free radical chlorination mechanism (Initiation, Propagation, Termination)']::TEXT[], '2 R-X + 2 Na --(dry ether)--> R-R + 2 NaX', true, true, 1),
  ('chem-hydrocarbons-2', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.2', 'Alkenes: Preparation & Geometrical Isomerism', '', ARRAY['Dehydrohalogenation of alkyl halides: Saytzeff (Zaitsev) rule (more substituted alkene is major)', 'Acid-catalyzed dehydration of alcohols', 'Cis vs Trans physical properties (Cis has higher dipole and boiling point; Trans has higher melting point due to symmetry)']::TEXT[], NULL, true, true, 2),
  ('chem-hydrocarbons-3', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.3', 'Alkene Reactions: Markovnikov Rule & Peroxide Effect', 'The peroxide effect (anti-Markovnikov) is ONLY observed with HBr, NEVER with HCl or HI.', ARRAY['Electrophilic addition of HX: Markovnikov rule (H adds to carbon with more H)', 'Peroxide effect (Kharasch effect): Anti-Markovnikov addition of HBr ONLY (does not work for HCl or HI due to endothermic propagation steps)', 'Ozonolysis of alkenes: Reductive cleavage using O₃ / Zn-H₂O to locate double bond position']::TEXT[], NULL, true, true, 3),
  ('chem-hydrocarbons-4', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.4', 'Alkynes: Acidity of Terminal Alkynes & Hydration', '', ARRAY['Acidic nature of terminal alkynes: HC≡CH reacts with Na or NaNH₂ (50% s-character in sp carbon stabilizes carbanion)', 'Hydration with 20% H₂SO₄ + 1% HgSO₄: Ethyne gives Acetaldehyde, all other alkynes give Ketones']::TEXT[], NULL, true, true, 4),
  ('chem-hydrocarbons-5', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.5', 'Aromaticity & Hückel''s (4n + 2) π-Electron Rule', '', ARRAY['Conditions for aromaticity: Planar, Cyclic, Completely conjugated, (4n + 2) π electrons', 'Anti-aromatic: 4n π electrons (highly unstable)', 'Examples: Benzene, Cyclopentadienyl anion, Tropylium cation']::TEXT[], '	ext{Aromatic } implies (4n + 2)pi 	ext{ electrons}, quad 	ext{Anti-aromatic } implies 4npi', true, true, 5),
  ('chem-hydrocarbons-6', 'chem-hydrocarbons', 'cbse-11-chemistry', '13.6', 'Electrophilic Aromatic Substitution (EAS) in Benzene', '', ARRAY['Mechanism of Nitration (HNO₃ + H₂SO₄ generates NO₂⁺ electrophile)', 'Halogenation (FeCl₃ + Cl₂ generates Cl⁺)', 'Friedel-Crafts Alkylation (RCl + AlCl₃, prone to carbocation rearrangement) & Acylation (RCOCl + AlCl₃, no rearrangement)', 'Activating & o/p directing (-OH, -NH₂, -CH₃) vs Deactivating & m-directing (-NO₂, -COOH, -CHO)']::TEXT[], NULL, true, true, 6),
