  ('math-straight-1', 'math-straight', 'cbse-11-mathematics', '10.1', 'Slope of a Line & Angle Between Two Lines', '', ARRAY['Slope m = tan θ = (y₂ - y₁) / (x₂ - x₁)', 'Parallel lines: m₁ = m₂', 'Perpendicular lines: m₁ m₂ = -1', 'Angle tan θ = |(m₂ - m₁) / (1 + m₁ m₂)|']::TEXT[], 'm_1 m_2 = -1 quad (perp), quad 	an	heta = left|rac{m_2 - m_1}{1 + m_1 m_2}ight|', true, true, 1),
  ('math-straight-2', 'math-straight', 'cbse-11-mathematics', '10.2', 'Forms of Equations of a Line', '', ARRAY['Slope-intercept form: y = mx + c', 'Point-slope form: y - y₁ = m(x - x₁)', 'Two-point form: y - y₁ = ((y₂ - y₁)/(x₂ - x₁))(x - x₁)', 'Intercept form: x/a + y/b = 1', 'Normal form: x cos ω + y sin ω = p']::TEXT[], 'rac{x}{a} + rac{y}{b} = 1, quad xcosomega + ysinomega = p', true, true, 2),
  ('math-straight-3', 'math-straight', 'cbse-11-mathematics', '10.3', 'General Equation of Line & Reduction to Standard Forms', '', ARRAY['Ax + By + C = 0 has slope m = -A/B, x-intercept = -C/A, y-intercept = -C/B']::TEXT[], NULL, false, true, 3),
  ('math-straight-4', 'math-straight', 'cbse-11-mathematics', '10.4', 'Distance of a Point from a Line', '', ARRAY['Perpendicular distance d = |Ax₁ + By₁ + C| / √(A² + B²)', 'Distance from origin: d = |C| / √(A² + B²)']::TEXT[], 'd = rac{|Ax_1 + By_1 + C|}{sqrt{A^2 + B^2}}', true, true, 4),
  ('math-straight-5', 'math-straight', 'cbse-11-mathematics', '10.5', 'Distance Between Parallel Lines', 'Make sure the coefficients of x and y are identical in both equations before taking |C₁ - C₂|!', ARRAY['Lines Ax + By + C₁ = 0 and Ax + By + C₂ = 0: d = |C₁ - C₂| / √(A² + B²)']::TEXT[], 'd = rac{|C_1 - C_2|}{sqrt{A^2 + B^2}}', true, true, 5),
  ('math-straight-6', 'math-straight', 'cbse-11-mathematics', '10.6', 'Family of Lines & Intersection Point', '', ARRAY['Equation of family passing through intersection of L₁ and L₂: L₁ + λ L₂ = 0']::TEXT[], NULL, false, true, 6),
  ('math-conic-1', 'math-conic', 'cbse-11-mathematics', '11.1', 'Circle: Standard & General Equations', '', ARRAY['Standard form: (x - h)² + (y - k)² = r²', 'General form: x² + y² + 2gx + 2fy + c = 0 with Centre (-g, -f) and Radius r = √(g² + f² - c)', 'Parametric equations: x = h + r cos θ, y = k + r sin θ']::TEXT[], 'r = sqrt{g^2 + f^2 - c}, quad 	ext{Centre: } (-g, -f)', true, true, 1),
  ('math-conic-2', 'math-conic', 'cbse-11-mathematics', '11.2', 'Parabola: 4 Standard Forms & Parameters', '', ARRAY['y² = 4ax (Focus (a, 0), Directrix x = -a, Latus Rectum = 4a)', 'y² = -4ax, x² = 4ay, x² = -4ay', 'Eccentricity e = 1', 'Focal distance of point (x₁, y₁) on y² = 4ax is (x₁ + a)']::TEXT[], 'y^2 = 4ax implies 	ext{Focus: } (a, 0), 	ext{ LR: } 4a', true, true, 2),
  ('math-conic-3', 'math-conic', 'cbse-11-mathematics', '11.3', 'Ellipse: Horizontal & Vertical Equations', '', ARRAY['x²/a² + y²/b² = 1 (a > b)', 'Eccentricity e = √(1 - b²/a²) < 1', 'Foci (±ae, 0), Directrices x = ±a/e', 'Length of Latus Rectum = 2b²/a', 'Sum of focal distances SP + S''P = 2a']::TEXT[], 'b^2 = a^2(1 - e^2), quad 	ext{Length of LR} = rac{2b^2}{a}', true, true, 3),
  ('math-conic-4', 'math-conic', 'cbse-11-mathematics', '11.4', 'Hyperbola: Standard & Conjugate', '', ARRAY['x²/a² - y²/b² = 1', 'Eccentricity e = √(1 + b²/a²) > 1', 'Foci (±ae, 0), Directrices x = ±a/e', 'Length of Latus Rectum = 2b²/a', 'Difference of focal distances |SP - S''P| = 2a', 'Rectangular hyperbola: a = b, e = √2']::TEXT[], 'b^2 = a^2(e^2 - 1), quad e = sqrt{1 + rac{b^2}{a^2}}', true, true, 4),
  ('math-conic-5', 'math-conic', 'cbse-11-mathematics', '11.5', 'Conic Identification by Eccentricity (e)', '', ARRAY['e = 0 (Circle), e = 1 (Parabola), 0 < e < 1 (Ellipse), e > 1 (Hyperbola)']::TEXT[], NULL, true, true, 5),
  ('c11-m11-t1', 'math-3d', 'cbse-11-mathematics', '11.1', '3D coordinate octants, distance formula d = sqrt((x2-x1)^2 + (y2-y1)^2 + (z2-z1)^2)', '', ARRAY['3D coordinate octants, distance formula d = sqrt((x2-x1)^2 + (y2-y1)^2 + (z2-z1)^2)']::TEXT[], NULL, false, true, 1),
