  ('math-limits-1', 'math-limits', 'cbse-11-mathematics', '13.1', 'Concept of Limit & Left/Right Hand Limits', '', ARRAY['Limit exists if and only if LHL = RHL = finite', 'Evaluating limits involving [x], |x|, sgn(x)']::TEXT[], NULL, true, true, 1),
  ('math-limits-2', 'math-limits', 'cbse-11-mathematics', '13.2', 'Algebra of Limits & Indeterminate Forms', '', ARRAY['Indeterminate forms (0/0, ∞/∞, 0 × ∞, ∞ - ∞)', 'Factoring and rationalization methods', 'Standard algebraic limit: lim_{x→a} (xⁿ - aⁿ)/(x - a) = n aⁿ⁻¹']::TEXT[], 'lim_{x 	o a}rac{x^n - a^n}{x - a} = n a^{n-1}', true, true, 2),
  ('math-limits-3', 'math-limits', 'cbse-11-mathematics', '13.3', 'Trigonometric Limits & Sandwich Theorem', 'lim_{x→0} (sin x)/x = 1 is true ONLY when x is measured in radians. If in degrees, answer is π/180.', ARRAY['lim_{x→0} (sin x)/x = 1 (x in radians)', 'lim_{x→0} (tan x)/x = 1', 'lim_{x→0} (1 - cos x)/x² = ½']::TEXT[], 'lim_{x 	o 0}rac{sin x}{x} = 1, quad lim_{x 	o 0}rac{1 - cos x}{x^2} = rac{1}{2}', true, true, 3),
