  ('c12-m13-t3', 'c12-math-13', 'cbse-12-mathematics', '13.3', 'Random variable and probability distribution table, Mean E(X) = Sum(x_i p_i)', '', ARRAY['Random variable and probability distribution table, Mean E(X) = Sum(x_i p_i)']::TEXT[], NULL, true, true, 3),
